INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (255, 0, 'ref-format', 'Format', 'Char ( number )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (255, 1, 'ref-param', 'Parameters', 'number - a decimal number representing one or more Unicode code points');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (255, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (255, 3, 'ref-orig', 'Originated in version', '10.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (255, 4, 'ref-desc', 'Description', 'Each group of five digits in the number is treated as a Unicode code point, and the character for each five-digit group is returned in the text.

If the number is 0, the function returns an empty string.

If the number is between 1 and 99,999, the function returns a single character.

If the number contains more than five digits, the function returns the string of characters represented by those code points.

For a list of common navigation characters and their Unicode code points, see the Code function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (255, 5, 'notes', 'Notes', '- Some Unicode characters can be represented by a single code point or multiple code points. For example, the character ä can be represented by the letter a plus ¨ (dieresis) or by the single character ä. The single code point version of this kind of character is called a precomposed character or a composite character.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (255, 6, 'ref-example1', 'Example 1', 'Char(0) returns an empty string ("").

Char(97) returns a.

Char(98) returns b.

Char(9800097) returns ab.

Char(228) returns ä.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (255, 7, 'ref-examplen', 'Example 2', 'Char(77600097) returns ä. In this case the number represents two Unicode characters: the letter a and the dieresis character. When these two characters appear together in a string they are displayed as a single character.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (255, 8, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas

- Code function');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (256, 0, 'ref-format', 'Format', 'Code ( text )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (256, 1, 'ref-param', 'Parameters', 'text - one or more characters');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (256, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (256, 3, 'ref-orig', 'Originated in version', '10.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (256, 4, 'ref-desc', 'Description', 'Returns the Unicode code points for the characters in text. If zero characters are in text, returns an empty string.

If one character is in the text, the function returns the code point for that character. If the text contains multiple characters, the Unicode code point for each character is returned as a group of five digits where the code point for the first character is represented by the low five digits, the code point for the second character in the next higher (to the left) five digits, and so forth.

When converting a composite character such as ä, the function returns the Unicode code point for the composite character.

The following table shows some common navigational characters and the corresponding values returned by this function. These are useful when testing which keystroke activated an OnLayoutKeystroke or OnObjectKeystroke script trigger.
For navigational key
Code returns
Notes
backspace
8
Corresponds to Unicode/ASCII code for BS (backspace)
tab
9
Corresponds to Unicode/ASCII code for HT (horizontal tab)
shift-tab
9
The shift can be detected using the value returned from the Get(TriggerModifierKeys) function
enter
 10
Corresponds to Unicode/ASCII code for LF (line feed)
return
 13
Corresponds to Unicode/ASCII code for CR (carriage return)
escape
 27
Corresponds to Unicode/ASCII code for ESC (escape)
left arrow
 28
Corresponds to Unicode/ASCII code for FS (file separator)
up arrow
 29
Corresponds to Unicode/ASCII code for GS (group separator)
right arrow
 30
Corresponds to Unicode/ASCII code for RS (record separator)
down arrow
 31
Corresponds to Unicode/ASCII code for US (unit separator)
space
 32
Corresponds to Unicode/ASCII code for Space
forward delete
127
Corresponds to Unicode/ASCII code for Delete');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (256, 5, 'notes', 'Notes', '-
If there are too many characters to be represented in a number field in a FileMaker Pro file, the function returns "?".');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (256, 6, 'ref-example1', 'Example 1', 'Code ( "" ) returns an empty string.

Code ( "a" ) returns 97.

Code ( "b" ) returns 98.

Code ( "ab" ) returns 9800097.

Code ( "ä" ) returns 228.

Code ( "ä" ) (an a followed by a dieresis character entered in a separate keystroke) returns 77600097.');
