INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 0, 'ref-format', 'Format', 'Exact ( originalText ; comparisonText )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 1, 'ref-param', 'Parameters', 'originalText - any text expression, text field, or container field

comparisonText - any text expression, text field, or container field');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 4, 'ref-desc', 'Description', 'For text to match exactly, the uppercase and lowercase usage must be the same. For container fields, the data must be stored in the same manner (either embedded, or stored by reference).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 5, 'notes', 'Notes', '- When evaluating values, text attributes such as font, styles, and sizes are not considered.

- If case isn''t important, use the Lower function or Upper function on both parameters to process data before checking for an exact match.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 6, 'ref-example1', 'Example 1', 'Exact ( "McDonald" ; "McDonald" ) returns 1 (True).

Exact ( "McDonald" ; "MCDONALD" ) returns 0 (False).

Exact ( "John" ; "John " ) returns 0 (False).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 7, 'ref-examplen', 'Example 2', 'Exact ( Upper ( "McDonald" ) ; Upper ( "MCDONALD" ) ) returns 1 (True).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 8, 'ref-examplen', 'Example 3', 'Exact ( BillTo ; ShipTo ) returns 1 (True) when the value in BillTo is the same as the value in ShipTo.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 9, 'ref-examplen', 'Example 4', 'Exact ( Recipient ; Upper ( Recipient ) ) returns 1 (True), when Recipient contains JOHNSON.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (257, 10, 'ref-examplen', 'Example 5', 'Exact ( Country ; "Spain" ) returns 1 (True) when the Country field contains Spain.');
