INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (258, 0, 'ref-format', 'Format', 'Filter ( textToFilter ; filterText )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (258, 1, 'ref-param', 'Parameters', 'textToFilter - any text expression or text field

filterText - the characters to preserve in the specified text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (258, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (258, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (258, 4, 'ref-desc', 'Description', 'If filterText doesn''t have any characters, an empty string is returned. The Filter function is case sensitive.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (258, 5, 'ref-example1', 'Example 1', 'Filter ( "(408)555-1212" ; "0123456789" ) returns 4085551212.

Filter ( "AaBb" ; "AB" ) returns AB.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (258, 6, 'ref-examplen', 'Example 2', 'The following example removes all text from the provided data, then formats the remaining numbers in the preferred phone number formatting:

Copy

Let (
   phone = filter ( theField ; "0123456789" ) ;
   "(" & Left ( phone ; 3 ) & ")" & Middle ( phone ; 4 ; 3 ) & "-" &
   Middle ( phone ; 7 ; 4 )
)

If theField contains Work: 408.555.1212 this calculation returns (408)555-1212.');
