INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (259, 4, 'ref-desc', 'Description', 'For a description of a list of values, see ValueCount function.

Each returned value ends with a carriage return, allowing lists to be easily concatenated.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (259, 5, 'notes', 'Notes', '- If the filterValues parameter doesn''t have any values, an empty string is returned.

- The FilterValues function is not case sensitive.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (259, 6, 'ref-example1', 'Example 1', 'FilterValues ( "Plaid¶Canvas¶Suitcase" ; "Plaid¶Canvas" ) returns Plaid¶Canvas¶.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (259, 7, 'ref-examplen', 'Example 2', 'FilterValues ( ValueListItems ( "Database" ; "Sizes" ) ; "Medium¶Small" ) returns Small¶Medium¶ when a database file named Database has a value list Sizes that contains Small¶Medium¶Large.');
