INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (260, 0, 'ref-format', 'Format', 'GetAsCSS ( text )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (260, 1, 'ref-param', 'Parameters', 'text - any text expression or text field');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (260, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (260, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (260, 4, 'ref-desc', 'Description', 'GetAsCSS returns the specified text in a span element with CSS properties.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (260, 5, 'notes', 'Notes', '- The GetAsCSS function does not return formats that are set in the Conditional Formatting dialog box.');
