INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (261, 0, 'ref-format', 'Format', 'GetAsDate ( text )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (261, 1, 'ref-param', 'Parameters', 'text - any text expression or text field containing text in the same format as the date on the system where the file was created');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (261, 2, 'ref-return', 'Data type returned', 'date');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (261, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (261, 4, 'ref-desc', 'Description', 'Use with formulas involving dates or date functions; use the GetAsDate or Date function to enter a date constant into a formula. The format of text date must be the same as the numeric date format on the system where the file was created.

You can also use this function to convert the number of days to a date. If you specify a number as the parameter, it has to be between 1 (for 1/1/0001) and 1460970 (for 12/31/4000).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (261, 5, 'notes', 'Notes', '- If the function returns a number instead of a date, go to the Specify Calculation dialog box and make sure the Calculation result is date.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (261, 6, 'ref-example1', 'Example 1', 'GetAsDate ( "03/03/2019" ) returns 3/3/2019. You can perform date operations on this result using the Date function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (261, 7, 'ref-examplen', 'Example 2', 'GetAsDate ( 737342 ) returns 10/10/2019. The number 737342 specifies the number of days since 1/1/0001.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (261, 8, 'ref-examplen', 'Example 3', 'Use the following formula to determine the number of days elapsed between values in two timestamp fields:

GetAsDate ( EndDate ) - GetAsDate ( StartDate ) returns 90 if the value in the field EndDate is 4/1/2019 1:00 AM and the value in the field StartDate is 1/1/2019 11:15 PM.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (261, 9, 'related', 'Related topics', '- Functions reference

- About formulas

