- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (263, 0, 'ref-format', 'Format', 'GetAsSVG ( text )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (263, 1, 'ref-param', 'Parameters', 'text - any text expression or text field');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (263, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (263, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (263, 4, 'ref-desc', 'Description', 'SVG is an internet text format similar to HTML or CSS. SVG supports more text formats than HTML, so SVG will represent what you have typed more accurately.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (263, 5, 'notes', 'Notes', '- The GetAsSVG function does not return formats that are set in the Conditional Formatting dialog box.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (263, 6, 'ref-example1', 'Example 1', 'GetAsSVG ( text ) returns the result shown below when the field text contains the word "Frank" and the word Frank has the following text attributes: Font = Helvetica, Font Size = 12 points, Font Color = red, Font Style = bold.

<stylelist>
<style#0>"font-family: ''Helvetica'';font-size: 12px;color:
#FF0000;font-weight: bold;text-align: left;",
Begin: 1, End: 5</style>
</stylelist>
<data>
<span style="0">Frank</span>
</data>');
