INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (264, 0, 'ref-format', 'Format', 'GetAsText ( data )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (264, 1, 'ref-param', 'Parameters', 'data - any number, date, time or timestamp expression, or a field containing a number, date, time, timestamp, or container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (264, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (264, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (264, 4, 'ref-desc', 'Description', 'Use with formulas involving text or text functions. The data returned can be a field type number, date, time, timestamp, or container.

For a container field, GetAsText returns external path information, text (when the container contains text that does not resolve into a valid path), or a question mark (?) if the container data is embedded in the database. For container data stored externally, data is returned in the format shown in the following example:

GetAsText(Container)returns

remote:cat.jpg
size:320,240
JPEG:Images/Animals/cat.jpg');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (264, 5, 'ref-example1', 'Example 1', 'GetAsText ( 45 ) returns 45.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (264, 6, 'ref-examplen', 'Example 2', '"You are " & GetAsText ( DaysDelinquent ) & " days late." returns You are 3 days late. when the value of DaysDelinquent is 3.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (264, 7, 'ref-examplen', 'Example 3', '"FY" & GetAsText ( FiscalYear ) returns FY98, if the FiscalYear number field contains 98.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (264, 8, 'related', 'Related topics', '- Functions reference

