- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (265, 0, 'ref-format', 'Format', 'GetAsTime ( text )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (265, 1, 'ref-param', 'Parameters', 'text - any text expression or text field containing a time');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (265, 2, 'ref-return', 'Data type returned', 'time');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (265, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (265, 4, 'ref-desc', 'Description', 'Use with formulas involving the Time or Timestamp function; use the GetAsTime or the Time function to enter a time constant into a formula. The format of the supplied time must be the same as the time format on the system where the file was created.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (265, 5, 'ref-example1', 'Example 1', 'GetAsTime ( "02:47:35" ) returns 2:47:35 when you select time as the calculation result. You can perform time calculations on this result.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (265, 6, 'ref-examplen', 'Example 2', 'GetAsTime ( "02:47:35" ) returns 1/1/0001 2:47:35 when you select timestamp as the calculation result.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (265, 7, 'ref-examplen', 'Example 3', 'Abs (GetAsTime ( "12:15 pm" ) - CheckOut ) returns 3:00:00 when the CheckOut time field contains 3:15 PM.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (265, 8, 'related', 'Related topics', '- Functions reference

