INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (266, 0, 'ref-format', 'Format', 'GetAsTimestamp ( text )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (266, 1, 'ref-param', 'Parameters', 'text - any text expression, or text, number, date, or time field');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (266, 2, 'ref-return', 'Data type returned', 'timestamp');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (266, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (266, 4, 'ref-desc', 'Description', 'Use with formulas involving timestamps. Text strings must be in the form of a date followed by a time. The format of text must be the same as the numeric date format and time format on the system where the file was created. A number is considered to be the number of seconds since 1/1/0001. There are 86400 seconds in each day.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (266, 5, 'ref-example1', 'Example 1', 'GetAsTimestamp ("4/5/2019 4:05:06" ) returns 4/5/2019 4:05:06 AM.

GetAsTimestamp ( 50000 ) returns 1/1/0001 1:53:20 PM.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (266, 6, 'related', 'Related topics', '- Functions reference

