- Defining calculation fields

- Using operators in formulas

- About timestamp fields');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (267, 0, 'ref-format', 'Format', 'GetAsURLEncoded ( text )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (267, 1, 'ref-param', 'Parameters', 'text - any text expression or text field');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (267, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (267, 3, 'ref-orig', 'Originated in version', '8.5');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (267, 4, 'ref-desc', 'Description', 'This function removes all styles from text. All characters are first converted to UTF-8 format. Most characters that are not permitted in URLs are converted to %HH format (a percent sign followed by the character''s hexadecimal value). The following reserved characters are not converted:

: - _ . ! ~ * '' ( )

See www.w3.org for more information on URL encoding.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (267, 5, 'ref-example1', 'Example 1', 'GetAsURLEncoded("Hello") returns Hello.

GetAsURLEncoded("San Francisco") returns San%20Francisco.

GetAsURLEncoded("français") returns fran%c3%a7ais.');
