INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (274, 5, 'ref-example1', 'Example 1', 'Middle ( "(408)555-9054" ; 2 ; 3 ) returns 408.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (274, 6, 'ref-examplen', 'Example 2', 'Middle ( PhoneNumber ; 2 ; 3 ) returns 408 when the PhoneNumber field contains (408) 555-9054.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (274, 7, 'ref-examplen', 'Example 3', 'Middle ("abcdefghij" ; 5 ; 2 ) returns ef.');
