INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (277, 0, 'ref-format', 'Format', 'PatternCount ( text ; searchString )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (277, 1, 'ref-param', 'Parameters', 'text - any text expression or text field

searchString - any text expression or text field representing the text you want to find');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (277, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (277, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (277, 4, 'ref-desc', 'Description', 'This function is not case sensitive. PatternCount begins at the start of text and counts each non-overlapping occurrence of searchString.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (277, 5, 'ref-example1', 'Example 1', 'PatternCount ( "Mississippi" ; "is" ) returns 2.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (277, 6, 'ref-examplen', 'Example 2', 'PatternCount ( "Mississippi" ; "issi" ) returns 1. A second possible occurrence starting at character 5 is not counted because it overlaps the first occurrence at characters 2 through 5.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (277, 7, 'ref-examplen', 'Example 3', 'PatternCount ( Attending ; "Guest" ) returns 1 if the Guest checkbox is one of the items selected in the Attending field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (277, 8, 'ref-examplen', 'Example 4', 'PatternCount ( Get ( AccountPrivilegeSetName ) ; "Read-Only Access" ) returns 0 if the current account access has the Full Access privilege set.');
