- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (278, 0, 'ref-format', 'Format', 'Position ( text ; searchString ; start ; occurrence )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (278, 1, 'ref-param', 'Parameters', 'text - any text expression or text field.

searchString - any text expression or text field representing the text you want to find.

start - any numeric expression, or field containing a number, representing the number of characters from the start of the text string at which to begin the search. A start value of 1 or less begins the search from the first character of the text string.

occurrence - any numeric expression or field containing a number, representing which instance of the text string you want to find. The scan begins at the start value and, if occurrence is positive, continues toward the end of the text string; if occurrence is negative, the scan continues toward the beginning of the text string. A zero value for occurrence is invalid and returns a result of zero.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (278, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (278, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (278, 4, 'ref-desc', 'Description', 'This function is not case sensitive. If searchString isn''t contained in text or if there was no specified occurrence, zero is returned.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (278, 5, 'ref-example1', 'Example 1', 'Position ( "Mississippi" ; "iss" ; 1 ; 1 ) returns 2.

Position ( "Mississippi" ; "iss" ; 1 ; 2 ) returns 5.

Position ( "Mississippi" ; "iss" ; 3 ; 1 ) returns 5.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (278, 6, 'ref-examplen', 'Example 2', 'Left ( Name ; Position ( Name ; " " ; 1 ; 1 ) - 1 ) returns William, when Name is a text field that contains William Smith.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (278, 7, 'ref-examplen', 'Example 3', 'Right ( Name ; Length ( Name ) - Position ( Name ; " " ; Length ( Name ) ; - 1 ) ) returns Smith.');
