INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (281, 5, 'ref-example1', 'Example 1', 'Replace ( "1234567" ; 5 ; 1 ; "X" ) returns 1234X67.

Replace ( "1234567" ; 5 ; 1 ; "XX" ) returns 1234XX67.

Replace ( "1234567" ; 5 ; 2 ; "X" ) returns 1234X7.

Replace ( "1234567" ; 5 ; 0 ; "X" ) returns 1234X567.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (281, 6, 'ref-examplen', 'Example 2', 'Replace ( "William" ; 3 ; 4 ; "NEW TEXT" ) returns WiNEW TEXTm.');
