INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (285, 0, 'ref-format', 'Format', 'SerialIncrement ( text ; incrementBy )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (285, 1, 'ref-param', 'Parameters', 'text - any text that also contains a number

incrementBy - any numeric expression to increment the text by');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (285, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (285, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (285, 4, 'ref-desc', 'Description', 'This function doesn''t remove the text in text, which normally happens when performing standard math against a value that contains text.

If the incrementBy value is a decimal number, then only the integer portion of incrementBy value is added to the last number in text. Any character other than a number is considered a separator. You can use both positive and negative incrementBy values.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (285, 5, 'ref-example1', 'Example 1', 'SerialIncrement ( "abc12" ; 1 ) returns abc13.

SerialIncrement ( "abc12" ; 7 ) returns abc19.

SerialIncrement ( "abc12" ; -1 ) returns abc11.

SerialIncrement ( "abc12" ; 1.2 ) returns abc13.

SerialIncrement ( "abc1.2" ; 1.2 ) returns abc1.3.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (285, 6, 'ref-examplen', 'Example 2', 'In this example, any character other than a number is considered to be a separator and the number on the far right is incremented.

SerialIncrement ( "abc123;999" ; 1) returns abc123;1000.');
