INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (287, 0, 'ref-format', 'Format', 'Substitute ( text ; searchString ; replaceString )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (287, 1, 'ref-param', 'Parameters', 'text - any text expression or text field

searchString - any text expression or text field

replaceString - any text expression or text field');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (287, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (287, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (287, 4, 'ref-desc', 'Description', 'This function is case sensitive. Compare to the Replace function.

Multiple substitutions are allowed when you enclose each pair of searchString and replaceString parameters within brackets [ ] and separate them with semicolons. Substitutions are performed in the order you specify, so one substitution may be further modified by subsequent substitutions. FileMaker clients support up to 999 nested substitute conditions. For example:

Copy

Substitute(text; [search1; replace1]; [search2; replace2]; ... [searchN; replaceN])');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (287, 5, 'ref-example1', 'Example 1', 'Substitute ( Description ; "WYSIWYG." ; "What you see is what you get." ) replaces every occurrence of the acronym "WYSIWYG." in the Description field with the phrase What you see is what you get.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (287, 6, 'ref-examplen', 'Example 2', 'Substitute ( text ; ["a";"A"] ; ["b";"B"] ) replaces every lowercase a or b with A or B.');
