INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (290, 5, 'notes', 'Notes', '-
The datatype and locale parameters affect only how this function determines uniqueness; the data is not sorted. Uniqueness is determined in the same manner as for indexing. See Choosing a language for indexing or sorting.

-
If you set the locale parameter to Unicode_Raw, this function will distinguish between values based on their Unicode numeric encoding, which for example, differentiates between characters with different case and diacritical marks.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (290, 6, 'ref-example1', 'Example 1', 'UniqueValues ( "34¶600¶18¶600¶18.0" ; 2 ) returns 34¶600¶18¶.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (290, 7, 'ref-examplen', 'Example 2', 'UniqueValues ( Product::Colors ) removes duplicates based on the default data type of text in a file in which the locale is English:

RED¶green¶yellow¶

when the Product::Colors field contains RED¶green¶red¶yellow¶.');
