INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (292, 0, 'ref-format', 'Format', 'ValueCount ( text )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (292, 1, 'ref-param', 'Parameters', 'text - any text expression or text field');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (292, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (292, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (292, 4, 'ref-desc', 'Description', 'Values are text items that each end with a carriage return. You can place several values together to create a carriage-return-delimited list of values. A value can be empty, a single character, a word, a sentence, or a paragraph. When you press Enter or Return you start creating a new value. If the last value is not empty, it will be recognized with or without a trailing carriage return.

When the list of values is a literal string as in the example below, you must insert a literal carriage return character (¶) between each item in the list. To insert a literal carriage return character, click the ¶ button in the Specify Calculation dialog box.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (292, 5, 'notes', 'Notes', '- ValueCount and other functions that work with lists of values recognize all of the following characters as separators between values:
Character name
Unicode code point
Line feed
10
Carriage return
13
Line separator
8232
Paragraph separator
8233

When referring to lists of values, "carriage return" is used to refer to any of these separator characters.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (292, 6, 'ref-example1', 'Example 1', 'ValueCount ( "Item 1¶Item 2¶Item 3¶" ) returns 3.

ValueCount ( "Item 1¶Item 2¶Item 3¶¶" ) returns 4 (the last value is empty).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (292, 7, 'ref-examplen', 'Example 2', 'ValueCount ( ValueListItems ( "Employees" ; "Employee Names" ) ) returns the total number of values in the Employee Names value list in the Employees database file.');
