INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (293, 4, 'notes', 'Notes', '- In addition to space, tab, enter, and carriage return characters, characters such as equal (=), ampersand (&), hyphen (-), and so on identify the beginning of a new word. For more information about word separators, search the Knowledge Base.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (293, 5, 'ref-example1', 'Example 1', 'WordCount ( "The sun is rising." ) returns 4.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (293, 6, 'ref-examplen', 'Example 2', 'WordCount ( Letter ) returns the total number of words in the Letter field. If the Letter field contains the text x=y=1.5, this example returns 3 because each equal (=) character identifies the beginning of a new word.');
