INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (294, 0, 'ref-format', 'Format', 'RGB ( red ; green ; blue )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (294, 1, 'ref-param', 'Parameters', 'red - any numeric expression or numeric field containing a value from 0 to 255

green - any numeric expression or numeric field containing a value from 0 to 255

blue - any numeric expression or numeric field containing a value from 0 to 255');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (294, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (294, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (294, 4, 'ref-desc', 'Description', 'Numbers returned by this function can be passed as the color parameter in the TextColor or TextColorRemove functions. The RGB function uses the following formula to calculate the result:

red * 2562 + green * 256 + blue

where 2562 = 65536

Tip To determine the RGB value of a color, in Layout mode, click the Fill color palette in the formatting bar and choose Other Color. Values are shown for each of the basic colors. In macOS, select the Color Sliders tab. Choose RGB Sliders from the list.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (294, 5, 'ref-example1', 'Example 1', 'RGB(255;0;0) returns 16711680 representing red.

RGB(0;255;0) returns 65280 representing green.

RGB(0;0;255) returns 255 representing blue.

RGB(0;0;0) returns 0 representing black.

RGB(255;255;255) returns 16777215 representing white.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (294, 6, 'ref-examplen', 'Example 2', 'Using a table with text fields FirstName and LastName, specify the following auto-enter calculation for a third field called FullName that displays FirstName in orange and LastName in purple:

Copy

TextColor(FirstName;RGB(255;165;0)) &" "& TextColor(LastName;RGB(160;32;240))');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (294, 7, 'related', 'Related topics', '- Functions reference

