- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (295, 0, 'ref-format', 'Format', 'TextColor ( text ; RGB ( red ; green ; blue ) )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (295, 1, 'ref-param', 'Parameters', 'text - any text expression or text field

RGB(red;green;blue) - any integer from 0 to 16777215 obtained by combining the red, green, and blue values (each ranging from 0 to 255) to represent a color');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (295, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (295, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (295, 4, 'ref-desc', 'Description', 'Use this function to change the color of text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (295, 5, 'notes', 'Notes', '- Text formatting options will be lost if the field type that is returned is something other than text.

- To determine the RGB value of a color, in Layout mode, click the Fill color palette in the formatting bar and choose Other Color. Values are shown for each of the basic colors. In macOS, select the Color Sliders tab. Choose RGB Sliders from the list.

- This function is not supported in FileMaker WebDirect.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (295, 6, 'ref-example1', 'Example 1', 'TextColor ( "Plaid" ; RGB ( 255 ; 0 ; 0 ) ) returns the word Plaid in red.

TextColor ( "Plaid" ; RGB ( 0 ; 255 ; 0 ) ) returns the word Plaid in green.

TextColor ( "Plaid" ; RGB ( 0 ; 0 ; 255 ) ) returns the word Plaid in blue.

TextColor ( "Plaid" ; RGB ( 0 ; 0 ; 0 ) ) returns the word Plaid in black.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (295, 7, 'ref-examplen', 'Example 2', 'TextSize ( TextFont ( TextColor ( MyTable::MyText ; RGB ( 0 ; 125 ; 125 ) ) ; "Courier" ) ; 12 ) returns the text contained in MyTable::MyText formatted as 12pt. green text with the Courier font.');
