- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (296, 0, 'ref-format', 'Format', 'TextColorRemove ( text {; RGB ( red ; green ; blue )} )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (296, 1, 'ref-param', 'Parameters', 'text - any text expression or text field.

RGB(red;green;blue) - any integer number from 0 to 16777215 obtained by combining the red, green, and blue values (each ranging from 0 to 255) to represent a color.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (296, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (296, 3, 'ref-orig', 'Originated in version', '8.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (296, 4, 'ref-desc', 'Description', 'Use this function to revert text to the default font color for the field. If you don''t use the RGB function to specify a color, all of the text displays in the default font color that was set in Layout mode for the field. When the font color is specified by the RGB function, only the specified font color is removed from every portion of the text displayed in that color and these same portions of the text are then displayed in the field''s default font color.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (296, 5, 'notes', 'Notes', '- Text formatting options will be lost if the field type that is returned is something other than text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (296, 6, 'ref-example1', 'Example 1', 'TextColorRemove ( "Red Text and Green Text" ) returns Red Text and Green Text displayed in the field''s default font color.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (296, 7, 'ref-examplen', 'Example 2', 'TextColorRemove ( "Red Text and Green Text" ; RGB ( 255 ; 0 ; 0 ) ) returns Red Text and Green Text with only the pure red font color removed from the words Red Text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (296, 8, 'related', 'Related topics', '- Functions reference

