INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (297, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (297, 4, 'ref-desc', 'Description', 'Spellings for font names must be correct. Text formatting options will be lost if the field type that is returned is something other than text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (297, 5, 'ref-example1', 'Example 1', 'TextFont ( "Plaid" ; "Courier" ) returns the word Plaid in the Courier font.

TextFont ( "Plaid" ; "Arial" ) returns the word Plaid in the Arial font.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (297, 6, 'ref-examplen', 'Example 2', 'TextSize ( TextFont ( TextColor ( MyTable::MyText ; RGB ( 0 ; 125 ; 125 ) ) ; "Courier" ) ; 12 ) returns the text contained in MyTable::MyText formatted as 12pt. green text with the Courier font.');
