INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (298, 0, 'ref-format', 'Format', 'TextFontRemove ( text {; fontToRemove } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (298, 1, 'ref-param', 'Parameters', 'text - any text expression or text field.

fontToRemove - any font name expressed in text.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (298, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (298, 3, 'ref-orig', 'Originated in version', '8.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (298, 4, 'ref-desc', 'Description', 'Use this function to revert text to the default for the field. If you don''t specify a font, all of the text displays in the default font that was set in Layout mode for the field. When the font is specified by fontToRemove, only the specified font is removed from every portion of the text displayed in that font and these same portions of the text are then displayed in the field''s default font.

Spellings for font names must be correct. Text formatting options will be lost if the field type that is returned is something other than text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (298, 5, 'ref-example1', 'Example 1', 'TextFontRemove ( "Arial Text and Courier Text" ) returns Arial Text and Courier Text displayed in the field''s default font.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (298, 6, 'ref-examplen', 'Example 2', 'TextFontRemove ( "Arial Text and Courier Text" ; "Arial" ) returns Arial Text and Courier Text with the Arial font removed from the words Arial Text.');
