INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (300, 5, 'ref-example1', 'Example 1', 'TextSize ( "Plaid" ; 18 ) returns the word Plaid in 18 point text.

TextSize ( "Plaid" ; 24 ) returns the word Plaid in 24 point text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (300, 6, 'ref-examplen', 'Example 2', 'TextSize ( TextFont ( TextColor ( MyTable::MyText ; RGB ( 0 ; 125 ; 125 ) ) ; "Courier" ) ; 12 ) returns the text contained in MyTable::MyText formatted as 12-point. green text with the Courier font.');
