INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (301, 1, 'ref-param', 'Parameters', 'text - any text expression or text field.

sizeToRemove - any font size expressed as an integer.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (301, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (301, 3, 'ref-orig', 'Originated in version', '8.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (301, 4, 'ref-desc', 'Description', 'Use this function to revert text to the default font size for the field. If you don''t specify a size, all of the text displays in the default font size that was set in Layout mode for the field. When the font size is specified by sizeToRemove, only the specified font size is removed from every portion of the text displayed in that size and these same portions of the text are then displayed in the field''s default font size.

The font size is described in points (72 points to the inch). Text formatting options will be lost if the field type that is returned is something other than text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (301, 5, 'ref-example1', 'Example 1', 'TextSizeRemove ( "10 Point Text and 18 Point Text" ) returns 10 Point Text and 18 Point Text displayed in the field''s default font size.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (301, 6, 'ref-examplen', 'Example 2', 'TextSizeRemove ( "10 Point Text and 18 Point Text" ; 18 ) returns 10 Point Text and 18 Point Text with the 18 point font size removed from the words 18 Point Text.');
