INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (302, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (302, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (302, 4, 'ref-desc', 'Description', 'You can add multiple styles by using the + operator between style names. Negative values are not valid. All styles will be removed, if the only style specified is Plain. Plain is ignored if mixed with other styles. Styles are not case sensitive and do not contain spaces.

Text formatting options will be lost if the field type that is returned is something other than text.

The styles that are available are:

- Plain

- Bold

- Italic

- Underline

- HighlightYellow

- Condense

- Extend

- Strikethrough

- SmallCaps

- Superscript

- Subscript

- Uppercase

- Lowercase

- Titlecase

- WordUnderline

- DoubleUnderline

- AllStyles (all available styles)');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (302, 5, 'notes', 'Notes', '- To format or change the case of text, use the Lower, Upper, or Proper function (see Text functions).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (302, 6, 'ref-example1', 'Example 1', 'TextStyleAdd ( "Plaid" ; Italic ) returns the word Plaid in italics.

TextStyleAdd ( FirstName ; Bold+Underline ) returns Sophie in bold, underlined text when the FirstName field contains Sophie.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (302, 7, 'ref-examplen', 'Example 2', 'The following calculation removes all styles from the text, then italicizes the entire phrase.

Copy

TextStyleAdd ( TextStyleAdd ( FirstName ; Plain ) ; Italic )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (302, 8, 'ref-examplen', 'Example 3', 'The following calculation creates two descriptions of styles, then concatenates two phrases using these styles. Using the Let function is an effective way to avoid creating a long and complex TextStyleAdd statement.

Copy

Let ( [
   TitleStyle = Smallcaps + Titlecase ;
   BodyStyle = Plain
] ;
TextStyleAdd ( titleField ; titleStyle ) & "¶¶" & TextStyleAdd ( bodyField ; BodyStyle ) )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (302, 9, 'ref-examplen', 'Example 4', 'In the following example, to find every occurrence of several words and change their style, use the Substitute function combined with the TextStyleAdd function.

Copy

Substitute ( ArticleBody ;
[ "Phrase1" ; TextStyleAdd ( "Phrase 1" ; Italic ) ] ;
[ "Phrase 2" ; TextStyleAdd ( "Phrase 2" ; Bold ) ] )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (302, 10, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (303, 0, 'ref-format', 'Format', 'TextStyleRemove ( text ; styles )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (303, 1, 'ref-param', 'Parameters', 'text - any text expression or text field

styles - any named style from the list of available styles');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (303, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (303, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (303, 4, 'ref-desc', 'Description', 'You can remove multiple styles by using the + operator between style names. Negative values are not valid. The Plain styles cannot be used for this function. Plain is ignored if intermingled with other styles. Styles are not case sensitive and do not contain spaces.

An additional style called AllStyles has been provided to make it easier to remove all styles. Text formatting options will be lost if the field type that is returned is something other than text.

The styles that are available are:

- Bold

- Italic

- Underline

- HighlightYellow

- Condense

- Extend

- Strikethrough

- SmallCaps

- Superscript

- Subscript

- Uppercase

- Lowercase

- Titlecase

- WordUnderline

- DoubleUnderline

- AllStyles (all available styles)');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (303, 5, 'ref-example1', 'Example 1', 'TextStyleRemove ( "Plaid" ; Italic ) returns the word Plaid with the italics style removed.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (303, 6, 'ref-examplen', 'Example 2', 'TextStyleRemove ( FirstName ; Bold + Underline ) returns Sophie with the bold and underlined styles removed when the FirstName field contains Sophie.

TextStyleRemove ( FirstName ; AllStyles ) returns Sophie without any styles.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (303, 7, 'ref-examplen', 'Example 3', 'TextStyleRemove ( MyTable::MyText ; HighlightYellow )returns the text contained in MyTable::MyText with the HighlightYellow style removed.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (303, 8, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (304, 0, 'ref-format', 'Format', 'Abs ( number )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (304, 1, 'ref-param', 'Parameters', 'number - any numeric expression or field containing a numeric expression');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (304, 2, 'ref-return', 'Data type returned', 'number, time');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (304, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (304, 4, 'ref-desc', 'Description', 'The absolute value of a number is positive. For example, if a negative number appears in a field, the Abs function removes the minus sign and changes it to a positive value.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (304, 5, 'ref-example1', 'Example 1', 'Abs(-123) returns 123.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (304, 6, 'ref-examplen', 'Example 2', 'Abs(PriceDifference) returns the positive value of the number in the PriceDifference field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (304, 7, 'ref-examplen', 'Example 3', 'Abs(TargetDate - ActualDate) returns a positive value for the number of days difference between the values in TargetDate and ActualDate.');
