INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (306, 0, 'ref-format', 'Format', 'Combination ( setSize ; numberOfChoices )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (306, 1, 'ref-param', 'Parameters', 'setSize - any numeric expression or field containing a non-negative numeric expression

numberOfChoices - any numeric expression or field containing a non-negative numeric expression');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (306, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (306, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (306, 4, 'ref-desc', 'Description', 'This function is useful in statistics, combinatorics, and polynomial expansions. The values returned by this function are referred to as combination coefficients. They form Pascal''s triangle.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (306, 5, 'ref-example1', 'Example 1', 'Combination(5;2) returns 10 for a set consisting of {a, b, c, d, e} because the unique choices when choosing two at a time are {ab, ac, ad, ae, bc, bd, be, cd, ce, de}.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (306, 6, 'ref-examplen', 'Example 2', '(13 * 12 * Combination(4;2) * Combination(4;3)) / Combination(52;5) returns 0.00144057..., which is the probability of being dealt a full-house in 5-card poker (less than a 1% chance).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (306, 7, 'related', 'Related topics', '- Functions reference

