INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (308, 0, 'ref-format', 'Format', 'Exp ( number )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (308, 1, 'ref-param', 'Parameters', 'number - any numeric expression or field containing a numeric expression');
