INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (308, 4, 'ref-desc', 'Description', 'This function returns the value of the constant e (the base of the natural logarithm, equal to 2.7182818) raised to the power of a number.

The Exp function is the inverse of the Ln function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (308, 5, 'ref-example1', 'Example 1', 'Exp(1) returns 2.71828182....

Exp(Ln(2)) returns 2.

Exp(0) returns 1.');
