Where n = number and i = numberOfFactors:');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (309, 5, 'ref-example1', 'Example 1', 'Factorial(3) returns 6, which = 3 * 2 * 1.

Factorial(10;3) returns 720, which = 10 * 9 * 8.');
