INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (315, 1, 'ref-param', 'Parameters', 'number - any numeric expression or field containing a numeric expression

divisor - numeric expression or field containing a numeric expression');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (315, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (315, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (315, 4, 'ref-desc', 'Description', 'Use the Mod function when converting units of measure, such as from minutes to hours, to return the number of remaining units.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (315, 5, 'ref-example1', 'Example 1', 'Calculates 210 divided by 4, with a remainder of 2.

Mod ( 210 ; 4 ) returns 2.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (315, 6, 'ref-examplen', 'Example 2', 'Converts the hours portion of a time from 24-hour notation to 12-hour notation. When the 24hTime field contains 16:

Mod ( 24hTime ; 12 ) returns 4.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (315, 7, 'ref-examplen', 'Example 3', 'Converts a number of months into a number of years and remaining months. When the NumberOfMonths field contains 31:

Int ( NumberOfMonths / 12 ) & " years, " & Mod ( NumberOfMonths ; 12 ) & " months" returns 2 years, 7 months.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (315, 8, 'related', 'Related topics', '- Functions reference

