- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (316, 0, 'ref-format', 'Format', 'Random');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (316, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (316, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (316, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (316, 4, 'ref-desc', 'Description', 'Returns a pseudo-random number in the range (0,1). FileMaker Pro generates a new random number when you:

- insert the Random function into a formula

- cause a formula containing the Random function to be reevaluated (by changing data in any of the fields the formula uses)

- display or access a calculation field defined to have an unstored result');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (316, 5, 'ref-example1', 'Example 1', 'Int ( Random * 10 ) returns a random number from 0 to 9.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (316, 6, 'ref-examplen', 'Example 2', 'Int ( Dice::NumSides * Random ) + 1 returns a randomly chosen side of a single die.

The following script calculates multiple die rolls, adds the rolls to a single variable, then displays the results in a custom dialog.

Copy

Loop [ Flush: Always ]
    Set Variable [$ROLL; Value:$ROLL + ( Int ( Test::NumSides * Random ) + 1 )]
    Set Variable [$COUNTER; Value:$COUNTER + 1]
    Exit Loop If [$COUNTER = Dice::NumDice]
End Loop
Show Custom Dialog [$ROLL]');
