INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (317, 1, 'ref-param', 'Parameters', 'number - any numeric expression or field containing a numeric expression

precision - any numeric expression or field containing a numeric expression for the number of decimal places');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (317, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (317, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (317, 4, 'ref-desc', 'Description', 'If you round a negative number of decimal places, all digits to the right of the decimal point are dropped, and the number is rounded to the nearest tens, hundreds, and so on. The Round function always rounds up at 0.5.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (317, 5, 'ref-example1', 'Example 1', 'Round(123.456;2) returns 123.46.

Round(14.5;0) returns 15.

Round(14.5;2) returns 14.5.

Round(29343.98;-3) returns 29000.

Round(123.456;-1) returns 120.');
