INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (318, 4, 'ref-desc', 'Description', 'All functions except trigonometric functions support extended precision. This function doesn''t perform a truncation.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (318, 5, 'ref-example1', 'Example 1', 'SetPrecision(5/9;30) returns 0.555555555555555555555555555556.

SetPrecision(1.321321321321321321321321321;0) returns 1.3213213213213213.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (318, 6, 'ref-examplen', 'Example 2', 'SetPrecision(If(field1>5;Exp(50);Average(5/9;1/7;5/7));25) returns either

5184705528587072464087.4533229334853848274691006 if field1 > 5, or

0.4708994708994708994708995 if field1 <= 5.');
