INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (321, 4, 'ref-desc', 'Description', 'This function doesn''t evaluate digits beyond the specified precision. Use the Round function to round up or down to the required precision.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (321, 5, 'ref-example1', 'Example 1', 'Truncate(123.456;2) returns 123.45.

Truncate(-14.6;0) returns -14.

Truncate(29343.98;-3) returns 29000.

Truncate(123.456;4) returns 123.456.

Truncate(29343.98;5) returns 29343.98.');
