INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (323, 5, 'ref-example1', 'Example 1', 'Day ( "5/15/2019" ) returns 15. This example assumes that the system date format is MM/DD/YYYY.

Day ( DateSold ) returns the day of the month stored in DateSold.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (323, 6, 'ref-examplen', 'Example 2', 'Displays the text Beware the Ides of March only when the day of the month returned by Get ( CurrentDate ) is 15 and the month returned by Get ( CurrentDate ) is 3; otherwise it displays nothing.

Copy

If (
   Day ( Get ( CurrentDate ) ) = 15 and Month ( Get ( CurrentDate ) ) = 3;
   "Beware the Ides of March" ;
   ""
)');
