INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (329, 0, 'ref-format', 'Format', 'WeekOfYear ( date )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (329, 1, 'ref-param', 'Parameters', 'date - any calendar date');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (329, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (329, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (329, 4, 'ref-desc', 'Description', 'Fractions of weeks occurring at the beginning or end of the year count as full weeks, so the WeekOfYear function returns values 1 to 54.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (329, 5, 'ref-example1', 'Example 1', 'WeekOfYear ( "1/1/2019" ) returns 1.

WeekOfYear ( ProjectDue ) returns 5, when ProjectDue is 2/2/2019.

WeekOfYear ( "1/1/2019" ) - WeekOfYear ( "2/2/2019" ) returns -4.');
