INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (331, 0, 'ref-format', 'Format', 'Year ( date )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (331, 1, 'ref-param', 'Parameters', 'date - any calendar date');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (331, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (331, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (331, 4, 'ref-desc', 'Description', 'You can, for example, extract the year from a field containing the date an item was sold.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (331, 5, 'ref-example1', 'Example 1', 'Year ( DateSold ) returns the year stored in DateSold.

Year ( "5/5/2019" ) returns 2019.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (331, 6, 'ref-examplen', 'Example 2', 'Returns the year that is 48 months from today''s date.

Copy

Year (
   Date (
      Month ( Get ( CurrentDate ) ) + 48 ;
      Day ( Get ( CurrentDate ) ) ;
      Year ( Get ( CurrentDate ) )
   )
)');
