INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (332, 6, 'ref-examplen', 'Example 3', 'Hour ( Duration ) + ( Minute ( Duration ) / 60 ) returns 2.5, when the Duration time field contains 2:30:15.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (332, 7, 'ref-examplen', 'Example 4', 'If ( Hour ( HoursWorked ) > 8 ; "Overtime Pay" ; " " ) returns Overtime Pay when the number of hours in HoursWorked is greater than 8.');
