INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (335, 0, 'ref-format', 'Format', 'Time ( hours ; minutes ; seconds )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (335, 1, 'ref-param', 'Parameters', 'hours - the hour value of a time

minutes - the minutes value of a time

seconds - the seconds value of a time');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (335, 2, 'ref-return', 'Data type returned', 'time');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (335, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (335, 4, 'ref-desc', 'Description', 'FileMaker Pro compensates when you supply fractional hours or minutes. The result is the time, formatted according to the time format of the field in the current layout.

Use the Time function or the GetAsTime function to enter a time constant into a formula.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (335, 5, 'ref-example1', 'Example 1', 'Time(4;14;32) returns 4:14:32.

Time(4.5;10;30) returns 4:40:30.

Time(4;15;70) returns 4:16:10.');
