INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (336, 1, 'ref-param', 'Parameters', 'date - any calendar date or date field

time - any time value or time field');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (336, 2, 'ref-return', 'Data type returned', 'timestamp');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (336, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (336, 4, 'ref-desc', 'Description', 'The format of the result depends on the date and time formats that were in use when the database file was created. You can change the date and time formats in your operating system.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (336, 5, 'ref-example1', 'Example 1', 'Timestamp ( Date ( 10 ; 21 ; 2019 ) ; Time ( 9 ; 10 ; 30 ) ) returns 10/21/2019 9:10:30 AM.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (336, 6, 'ref-examplen', 'Example 2', 'Timestamp ( Date ( 10 ; 21 ; 2019 ) ; Time ( 13 ; 10 ; 30 ) ) returns 10/21/2019 1:10:30 PM.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (336, 7, 'ref-examplen', 'Example 3', 'Timestamp ( Date ( 10 ; 21 ; 2019 ) ; Time ( 10 ; 65 ; 5 ) ) returns 10/21/2019 11:05:05 AM.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (336, 8, 'ref-examplen', 'Example 4', 'Timestamp ( Date ( 10 ; 35 ; 2019 ) ; Time ( 4 ; 5 ; 6 ) ) returns 11/4/2019 4:05:06 AM.');
