INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (337, 0, 'ref-format', 'Format', 'Base64Decode ( text {; fileNameWithExtension } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (337, 1, 'ref-param', 'Parameters', 'text - Base64 text to decode.

fileNameWithExtension - the filename and extension for the file created from the decoded Base64 text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (337, 2, 'ref-return', 'Data type returned', 'text, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (337, 3, 'ref-orig', 'Originated in version', '13.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (337, 4, 'ref-desc', 'Description', 'To decode a Base64-encoded value and return the result in a text field (or a variable used as text data), for the data parameter, specify text that was in UTF-8 format and then Base64 encoded.

To decode a Base64-encoded value that represents binary data, return the result in a container field (or a variable used as container data) and specify the fileNameWithExtension parameter. If a filename and extension are not specified, this function returns text rather than container data.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (337, 5, 'ref-example1', 'Example 1', 'Base64Decode(Products::Base64;"question.png") returns  when Products::Base64 is set to a string that begins with "iVBORw0KGgoAAAANSUhEUgAAAB8". The Base64 string in this example was shortened for readability.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (337, 6, 'related', 'Related topics', '- Base64Encode function

- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (338, 0, 'ref-format', 'Format', 'Base64Encode ( data )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (338, 1, 'ref-param', 'Parameters', 'data - any text expression or field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (338, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (338, 3, 'ref-orig', 'Originated in version', '13.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (338, 4, 'ref-desc', 'Description', 'This function converts text in text fields, variables, and calculations to UTF-8 format before encoding it (container data is not converted before encoding it). Base64Encode follows the RFC 2045 standard for formatting Base64-encoded text. See Base64EncodeRFC function.

Base64 encoding does not retain the filename or extension of encoded container field content.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (338, 5, 'ref-example1', 'Example 1', 'Base64Encode(Products::Color) returns QmxhY2s= when Products::Color is set to "Black".');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (338, 6, 'ref-examplen', 'Example 2', 'Base64Encode(Products::Container) returns a string that begins with iVBORw0KGgoAAAANSUhEUgAAAB8 when Products::Container is set to . The Base64 string in this example was shortened for readability.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (338, 7, 'related', 'Related topics', '- Base64Decode function

- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (339, 0, 'ref-format', 'Format', 'Base64EncodeRFC ( RFCNumber ; data )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (339, 1, 'ref-param', 'Parameters', 'RFCNumber - a number representing the IETF RFC standard of the Base64 format to use.

data - any text expression or field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (339, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (339, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (339, 4, 'ref-desc', 'Description', 'This function is similar to Base64Encode, except that you can specify the formatting to use.

For the RFCNumber parameter, use one of the following values to specify the RFC standard to follow for formatting Base64-encoded text. If you use an unrecognized value, this function defaults to RFC 4648.
RFCNumber
Encodes text with
1421
Maximum line length of 64 and CRLF (carriage return, line feed) line endings
2045
Maximum line length of 76 and CRLF line endings
3548
No line breaks added
4648
No line breaks added
4880
Maximum line length of 76, CRLF line endings, and an appended 24-bit CRC value');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (339, 5, 'ref-example1', 'Example 1', 'Base64EncodeRFC ( 4648 ; Products::Color ) returns QmxhY2s= when Products::Color is set to "Black".');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (339, 6, 'ref-examplen', 'Example 2', 'Base64EncodeRFC ( 1421 ; Products::Container ) returns a string whose first line is the following when Products::Container is set to .

iVBORw0KGgoAAAANSUhEUgAAAB8AAAARCAYAAAAlpHdJAAAAAXNSR0IArs4c6QAA

Each 64-character line ends with carriage return and line feed characters.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (339, 7, 'related', 'Related topics', '- Base64Decode function

- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (340, 0, 'ref-format', 'Format', 'CryptAuthCode ( data ; algorithm ; key )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (340, 1, 'ref-param', 'Parameters', 'data - any text expression or field from which to generate the HMAC.

algorithm - the name of the cryptographic algorithm to use (see below).

key - any expression or field as the key to encode the hash with.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (340, 2, 'ref-return', 'Data type returned', 'container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (340, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (340, 4, 'ref-desc', 'Description', 'Use the Base64EncodeRFC and Base64Decode or HexEncode and HexDecode functions to control the encoding of the key and the returned HMAC.

For the algorithm parameter, use one of the following names to specify the cryptographic algorithm:

-
MD5

-
SHA1

-
SHA224

-
SHA256

-
SHA384

-
SHA512

If algorithm is empty (""), the SHA512 algorithm is used; an unrecognized name causes this function to return "?".');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (340, 5, 'ref-example1', 'Example 1', 'In the Results container field, stores a file containing an HMAC of the text in the Message field. The HMAC is encoded with the value in the Key field using the default algorithm.

Copy

Set Field [ Table::Results ; CryptAuthCode ( Table::Message ; "" ; Table::Key ) ]');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (340, 6, 'ref-examplen', 'Example 2', 'Returns an HMAC of the contents of the $JSON variable using the SHA512 algorithm and a hex-encoded key $Key. The container data returned by CryptAuthCode is returned as Base64-encoded text.

Copy

Base64EncodeRFC ( 4648; CryptAuthCode ( $JSON ; "SHA512" ; HexDecode ( $Key ; "key.data" ) ) )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (340, 7, 'related', 'Related topics', '-
Functions reference

-
About formulas

-
About functions

-
Defining calculation fields

-
Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (341, 0, 'ref-format', 'Format', 'CryptDecrypt ( container ; key )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (341, 1, 'ref-param', 'Parameters', 'container - container data returned by the CryptEncrypt function.

key - any text expression or field that contains the same key that was used to encrypt container.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (341, 2, 'ref-return', 'Data type returned', 'text, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (341, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (341, 4, 'ref-desc', 'Description', 'This function accepts container data created by the CryptEncrypt function and the same key that was used to encrypt the data. The decrypted data is returned as the same type (text or container data) it was before encryption.

See FileMaker Security Guide.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (341, 5, 'ref-example1', 'Example 1', 'Returns This needs protection, the text that was encrypted using CryptEncrypt with the same key.

Copy

CryptDecrypt (
    CryptEncrypt ( "This needs protection" ; "My secret password" ) ;
    "My secret password"
)');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (341, 6, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (342, 0, 'ref-format', 'Format', 'CryptDecryptBase64 ( text ; key )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (342, 1, 'ref-param', 'Parameters', 'text - any text expression or text field that contains data returned by the CryptEncryptBase64 function.

key - any expression or field that contains the same key that was used to encrypt text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (342, 2, 'ref-return', 'Data type returned', 'text, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (342, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (342, 4, 'ref-desc', 'Description', 'This function works the same as the CryptDecrypt function, except that it accepts Base64-encoded text returned by the CryptEncryptBase64 function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (342, 5, 'ref-example1', 'Example 1', 'Returns This needs protection, the text that was encrypted using CryptEncryptBase64 with the same key.

Copy

CryptDecryptBase64 (
    CryptEncryptBase64 ( "This needs protection" ; "My secret password" ) ;
    "My secret password"
)');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (342, 6, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (343, 0, 'ref-format', 'Format', 'CryptDigest ( data ; algorithm )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (343, 1, 'ref-param', 'Parameters', 'data - any text expression or field from which to generate the hash.

algorithm - the name of the cryptographic algorithm to use (see CryptAuthCode function).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (343, 2, 'ref-return', 'Data type returned', 'container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (343, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (343, 4, 'ref-desc', 'Description', 'Use the Base64EncodeRFC and Base64Decode or HexEncode and HexDecode functions to control the encoding of the returned hash.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (343, 5, 'ref-example1', 'Example 1', 'In the Results container field, stores a file containing the digest of the text in the Message field using the default algorithm.

Copy

Set Field [ Table::Results ; CryptDigest ( Table::Message ; "" ) ]');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (343, 6, 'ref-examplen', 'Example 2', 'Returns a digest of the contents of the $JSON variable using the SHA512 algorithm. The container data returned by CryptDigest is returned as Base64-encoded text.

Copy

Base64EncodeRFC ( 4648; CryptDigest ( $JSON ; "SHA512" ) )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (343, 7, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
