INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (344, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (344, 4, 'ref-desc', 'Description', 'Use the CryptEncrypt and CryptDecrypt functions to encrypt and decrypt field data. CryptEncrypt accepts text or container data and returns container data as a binary file named encrypted.data.

See FileMaker Security Guide.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (344, 5, 'ref-example1', 'Example 1', 'Returns container data in a file named encrypted.data.

Copy

CryptEncrypt ( "This needs protection" ; "My secret password" )');
