This function works the same as the CryptEncrypt function, except that it returns encrypted data as Base64-encoded text following the RFC 4648 standard.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (345, 5, 'notes', 'Notes', '- Encoding binary data as Base64-encoded text increases its size by one third.');
