INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (346, 0, 'ref-format', 'Format', 'CryptGenerateSignature ( data ; algorithm ; privateRSAKey ; keyPassword )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (346, 1, 'ref-param', 'Parameters', 'data - any text expression to generate a signature from.

algorithm - the name of the cryptographic algorithm to use (see CryptAuthCode function).

privateRSAKey - text that represents an RSA private key. Optionally, the key may be encrypted.

keyPassword - the password to decrypt privateRSAKey with. If privateRSAKey is not encrypted, this parameter is ignored.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (346, 2, 'ref-return', 'Data type returned', 'container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (346, 3, 'ref-orig', 'Originated in version', '18.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (346, 4, 'ref-desc', 'Description', 'To generate a signature, this function first calculates the message digest of the data parameter using the specified algorithm. Then the digest is encrypted with the privateRSAKey parameter. If the private key is itself encrypted, you must provide the password as the last parameter, keyPassword.

An unencrypted RSA private key must be in this format:

Copy

-----BEGIN RSA PRIVATE KEY-----
MIIJKQIBAAKCAgEAqqDiwrPQwVaJzOzfFVBdhNjRNRxghZVQ9a3S88so8piw0uRt
...
A4jh5ffbGA6rlv1kEt1Inq2XDnKASjnWQGltDWWTJFs/XBcfoFXHpYiVINmp
-----END RSA PRIVATE KEY-----

An encrypted RSA private key must be in this format:

Copy

-----BEGIN RSA PRIVATE KEY-----
Proc-Type: 4,ENCRYPTED
DEK-Info: DES-EDE3-CBC,B2EFE673714F681D

gMvo1cn1+Sjch4cPXT/Mty0pILnsbM5SsBPadRJJQtrGrM8LkkrRNdxYRBeIGUMj
...
lHGJJBHogUW4Ig3/kd4ROVHusRYLtyyfz13A96tIl6Y7lu2L7alNWQ==
-----END RSA PRIVATE KEY-----

To generate an RSA key pair, you can use the OpenSSL toolkit. See www.openssl.org.

This function returns a binary signature of data as container data, or it returns "?" if any of the parameters are invalid. You can convert the container data into text using the Base64EncodeRFC function or HexEncode function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (346, 5, 'ref-example1', 'Example 1', 'Uses the SHA-512 algorithm with an encrypted private key to sign the data in the Table::TextToSign text field. The signature is returned as Base64-encoded text.

Copy

Base64EncodeRFC ( 4648 ;
    CryptGenerateSignature (
        Table::TextToSign ; "SHA512" ; Table::PrivateRSAKey ; $Password
    )
)');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (346, 6, 'related', 'Related topics', '- CryptVerifySignature function

- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (347, 0, 'ref-format', 'Format', 'CryptVerifySignature ( data ; algorithm ; publicRSAKey ; signature )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (347, 1, 'ref-param', 'Parameters', 'data - any text expression that represents the data to verify against signature.

algorithm - the name of the cryptographic algorithm to use (see CryptAuthCode function).

publicRSAKey - text that represents the PKCS #1 RSA public key in PEM format corresponding to the private key used to generate signature.

signature - the binary RSA signature to verify against data, such as the value returned by the CryptGenerateSignature function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (347, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (347, 3, 'ref-orig', 'Originated in version', '18.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (347, 4, 'ref-desc', 'Description', 'To verify a signature, this function compares the message digest of data (using the specified algorithm) to the digest obtained by decrypting signature using publicRSAKey.

An RSA public key must be in this format:

Copy

-----BEGIN PUBLIC KEY-----
MIICIjANBgkqhkiG9w0BAQEFAAOCAg8AMIICCgKCAgEAqqDiwrPQwVaJzOzfFVBd
...
egkXva5cYBb8PNifmlPXVb8CAwEAAQ==
-----END PUBLIC KEY-----

If the signature is valid for the data, this function returns 1 (true); if the signature is not valid, it returns 0 (false). If any of the parameters are invalid, it returns "?".');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (347, 5, 'ref-example1', 'Example 1', 'Uses the SHA-512 algorithm to generate the digest of Table::SignedText. Base64-decodes the signature stored in the Table::Signature text field and returns it as container data. Decrypts the signature using the value in the Table::PublicRSAKey field and compares the signature digest with the digest based on the Table::SignedText field. If the signature is valid, returns 1.

Copy

CryptVerifySignature (
    Table::SignedText ; "SHA512" ; Table::PublicRSAKey ;
    Base64Decode (
        Table::Signature ; "sig.data"
    )
)');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (347, 6, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (348, 0, 'ref-format', 'Format', 'GetContainerAttribute ( field ; attributeName )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (348, 1, 'ref-param', 'Parameters', 'field - any expression that returns container data.

attributeName - the name of a supported attribute (see below).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (348, 2, 'ref-return', 'Data type returned', 'text, number, date, time, timestamp, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (348, 3, 'ref-orig', 'Originated in version', '13.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (348, 4, 'ref-desc', 'Description', 'Some attributes may not return a result. For example, the values for the latitude and longitude of a photo may not be available, or some audio metadata like album art may not be available because the metadata is stored outside the audio file. Some individual attributes in the group attribute all may not be applicable in some circumstances.

In addition, when databases are hosted on Windows or Cloud and accessed via REST APIs, some attributes from the GetContainerAttribute function (for example, photo, created, modified, and all) may return invalid values.

Attributes
Attribute
Returns
Data type returned
General


filename
The name of the file inserted into the container field.
text
MD5
The result of applying the cryptographic hash function MD5 to a file inserted into the container field or a file referenced by a container field.
text
storageType
The method used to store the data in the container field: Embedded, External (Secure), External (Open), File Reference, Text.
text
fileSize
The size (in bytes) of the file inserted into the container field.
number
internalSize
The amount (in bytes) of the space inside the database file that is occupied by the container field.
number
externalSize
The amount (in bytes) of the space that is stored externally by the container field. This is either the size of the referenced file or the total size of all files in the container field (set up for open or secure storage).
number
externalFiles
A list of the external files associated with the container field (either files using open or secure storage or a file reference).
text



Images


width
A number representing the width of the image in pixels.
number
height
A number representing the height of the image in pixels.
number
dpiWidth
A number representing the horizontal DPI of the image.
number
dpiHeight
A number representing the vertical DPI of the image.
number
transparency
1 if the image has an alpha channel, otherwise returns 0.
number



Photos



Note Only HEIC, JPEG, and TIFF files return results.

orientation
A number representing the orientation of the photo:
1 (Normal)
2 (Flipped horizontally)
3 (Rotated 180 degrees)
4 (Flipped vertically)
5 (Rotated 90 degrees counterclockwise and flipped vertically)
6 (Rotated 90 degrees counterclockwise)
7 (Rotated 90 degrees clockwise and flipped vertically)
8 (Rotated 90 degrees clockwise)

Note Photos that were inserted using earlier versions of FileMaker clients are not automatically oriented; for such photos, not applied is appended to the result. For example, 3 (Rotated 180 degrees), not applied.
text
created
The earliest available timestamp for the photo.
timestamp
modified
The latest available timestamp for the photo. If the photo has never been modified, an empty string is returned.
timestamp
latitude
The latitude of the location of the photo.
text
longitude
The longitude of the location of the photo.
text
make
The manufacturer of the camera used for the photo.
text
model
The camera model used for the photo.
text



Audio



Note Only MP3 and M4A files return results.

title
The title of the audio.
text
artist
The name of the performer of the audio.
text
album
The name of the album containing the audio.
text
year
The year the audio was released.
text
track
The track number and count of the audio. For example, 3/12, or 3 if the track count is not available.
text
genre
The genre of the audio.
text
composer
The composer of the audio.
text
coverArt
An image of the album cover.
container
duration
The duration of the audio. For example, 0:03:16.
time
bitRate
The number of kilobits per second (kbps) used in the audio.
number



Barcodes


barcodeText
The contents of the barcode.
text
barcodeType
The type of the barcode.
text



Signatures


signed
The timestamp when the signature was inserted.
timestamp



Groups


general
Attributes listed in the General category above pertaining to the container field.
text
audio
Attributes listed in the Audio category above pertaining to the container field.
text
image
Attributes listed in the Images category above pertaining to the container field.
text
photo
Attributes listed in the Photos category above pertaining to the container field.
text
barcode
Attributes listed in the Barcodes category above pertaining to the container field.
text
signature
Attributes listed in the Signatures category above pertaining to the container field.
text
all
Attributes in all the categories listed above pertaining to the container field.
text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (348, 5, 'notes', 'Notes', '- Barcodes and signatures are not considered images.

- The internalSize can be much smaller than the fileSize (for example, container fields set up for open or secure storage, file references, or compressed files) or much larger than the fileSize (for example, container fields created by plug-ins).

- Using the attribute MD5 allows you to prevent the insertion of duplicated files into a container field regardless of the filename.

- For the group attributes general, audio, image, photo, and all, attributes are displayed in the format attributeName: attributeValue with one attribute per line. Some attributes are displayed differently in order to fit the attribute on one line:

- externalFiles. Displays only the number of external files.

- transparency. Displays 1 (True) or 0 (False).

- coverArt. Displays png or jpg depending on the type of image.

- bitRate. Displays kbps after the number. If an audio uses a variable bit rate, (VBR) is appended to the result. For example: Bit Rate: 247 kbps (VBR).

- year. Date information may be returned in parentheses after the year. For example: Year: 2019 (11/10/2019).

- Each returned value, except the last, ends with a carriage return.

- To minimize the frequency with which FileMaker Pro analyzes container data, use GetContainerAttribute in a field''s auto-enter calculation and deselect Do not replace existing value of field (if any). In this case, GetContainerAttribute will update only when the contents of the specified container field change. If GetContainerAttribute is used in a calculation field definition, the calculation may update each time the current record changes, reducing the performance of your custom app.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (348, 6, 'ref-example1', 'Example 1', 'Notice that the attributes in the following examples are enclosed in quotation marks.

GetContainerAttribute(Image;"all") returns:

[General]

Filename: IMG_003.JPG

Storage Type: Embedded

MD5: C35A3F668A1FB3F370969399A1FF04FE

File Size: 1964978

Internal Size: 1965064

External Size: 0

External Files: 0

[Image]

Width: 1936

Height: 2592

DPI Width: 72

DPI Height: 72

Transparency: 0 (False)

[Photo]

Orientation: 6 (Rotated 90 degrees counterclockwise)

Created: 1/14/2020 2:40:31 PM

Modified:

Latitude: 37.406167

Longitude: -121.983333

Make: Apple

Model: iPhone 11');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (348, 7, 'ref-examplen', 'Example 2', 'GetContainerAttribute(Product;"barcode") returns:

[Barcode]

Barcode Text: 875720001107

Barcode Type: UPC-A');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (348, 8, 'ref-examplen', 'Example 3', 'GetContainerAttribute(Package;"signature") returns:

[Signature]

Signed: 11/10/2019 11:41:22 AM');
