INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (350, 0, 'ref-format', 'Format', 'GetLiveText ( container ; language )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (350, 1, 'ref-param', 'Parameters', 'container - any expression that returns container data.

language - the language code of the text-recognition algorithm to use (see below).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (350, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (350, 3, 'ref-orig', 'Originated in version', '19.5');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (350, 4, 'ref-desc', 'Description', 'Use this function to capture the text found in the image in the specified container field using the text-recognition algorithm on supported versions of iOS, iPadOS, and macOS.

For language, use one of the following language codes to specify the text-recognition algorithm:

-
"en-US"

-
"fr-FR"

-
"it-IT"

-
"de-DE"

-
"es-ES"

-
"pt-BR"

-
"zh-Hans"

-
"ja-JP"

-
"ko-KR"

-
"uk-UA"

-
"th-TH"

-
"vi-VN"

-
"ar-SA"1

-
"ars-SA"1

-
Supported in operating systems starting with iOS 18, iPadOS 18 and macOS 15.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (350, 5, 'notes', 'Notes', '-
This function works with the following image formats: PNG, JPEG, GIF, TIFF, BMP, and PDF. PNG images with a transparent background aren''t supported.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (350, 6, 'ref-example1', 'Example 1', 'In the InvoiceText field, stores the text extracted from the image in the InvoiceContainer field using the en-US text-recognition algorithm.

Copy

Set Field [Invoices::InvoiceText ; GetLiveText ( Invoices::InvoiceContainer ; "en-US" )]');
