INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (351, 0, 'ref-format', 'Format', 'GetLiveTextAsJSON ( container ; language )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (351, 1, 'ref-param', 'Parameters', 'container - any expression that returns container data.

language - the language code of the text-recognition algorithm to use (see GetLiveText).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (351, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (351, 3, 'ref-orig', 'Originated in version', '21.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (351, 4, 'ref-desc', 'Description', 'This function is similar to the GetLiveText function, except that it returns an array of JSON objects, one for each text segment in the image. Each object contains the text and its position in this format:

Copy

[
    {
        "x": 10,
        "y": 20,
        "text": "Segment of text"
    },
    ...
]

The values for x and y are in pixels from the top left corner of the image.

For details on supported language codes and operating system versions, see GetLiveText.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (351, 5, 'ref-example1', 'Example 1', 'In the InvoiceText field, stores the text extracted from the image in the InvoiceContainer field using the en-US text-recognition algorithm.

Copy

Set Field [Invoices::InvoiceText ; GetLiveText ( Invoices::InvoiceContainer ; "en-US" )]

Sets the InvoiceText field to:

Copy

[
    {
        "x": 113,
        "y": 230,
        "text": "Erickson''s Water Garden"
    },
    {
        "x": 288,
        "y": 230,
        "text": "Alea Marks"
    },
    {
        "x": 421,
        "y": 230,
        "text": "2053 Lorem Rd."
    },
    {
        "x": 493,
        "y": 230,
        "text": "12/22/2019"
    }
]');
