INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (353, 0, 'ref-format', 'Format', 'GetThumbnail ( field ; width ; height )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (353, 1, 'ref-param', 'Parameters', 'field - any expression that returns container data.

width - the maximum width for the thumbnail.

height - the maximum height for the thumbnail.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (353, 2, 'ref-return', 'Data type returned', 'container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (353, 3, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (353, 4, 'ref-desc', 'Description', 'Returns an image as container data that''s no larger than the specified values for width and height. The thumbnail image always maintains the proportions of the original image and has a resolution of 72 dpi. Thumbnails cannot be made larger than the image''s original size.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (353, 5, 'notes', 'Notes', '-
This function returns a thumbnail image only if the Generate and store thumbnails for images option is selected in the Manage Containers dialog box. If this option is deselected, the image is returned at its original size. See Managing performance with thumbnails.

-
If the field parameter does not specify a field that contains image data, field must evaluate to the file path of an image. See Creating file paths.

-
For supported image formats, see Using data in container fields.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (353, 6, 'ref-example1', 'Example 1', 'Exports a thumbnail with a maximum height and width of 50 points.

Copy

Set Field [ Invoices::ExportContainer ; GetThumbnail ( Invoices::Container ; 50 ; 50 ) ]
Export Field Contents [ Invoices::ExportContainer ; Create folders: Off ]');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (353, 7, 'ref-examplen', 'Example 2', 'Creates a thumbnail, exports it, and attaches it to an email.

Copy

Set Field [ Invoices::ExportContainer ; GetThumbnail ( Invoices::Container ; 50 ; 50 ) ]
Set Variable [ $ATTACHMENT ; Value: Get ( TemporaryPath ) & GetContainerAttribute ( Invoices::ExportContainer ; "filename" ) ]
Export Field Contents [ Invoices::ExportContainer ; "$ATTACHMENT" ; Create folders: Off ]
Send Mail [ Send via E-mail Client ; With dialog: Off ; To: Customers::Email ; "$ATTACHMENT" ]');
