INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (355, 1, 'ref-param', 'Parameters', 'data - text expression or text field that contains hexadecimal data to decode.

fileNameWithExtension - text expression or text field that contains the filename and extension to use when the returned content is stored in a container field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (355, 2, 'ref-return', 'Data type returned', 'text, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (355, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (355, 4, 'ref-desc', 'Description', 'To decode a hexadecimal value and return the result in a text field (or a variable used as text data), for the data parameter, specify text that was in UTF-8 format and then hex encoded.

To decode a hexadecimal value that represents binary data, return the result in a container field (or a variable used as container data) and specify the fileNameWithExtension parameter. If a filename and extension are not specified, this function returns text rather than container data.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (355, 5, 'ref-example1', 'Example 1', 'HexDecode ( "46696C654D616B6572" ) returns FileMaker.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (355, 6, 'ref-examplen', 'Example 2', 'Decodes hexadecimal data in a text field and stores it as a file named key.data in a container field.

Copy

