For the encoding parameter, use one of the values defined for the TextEncode function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (358, 5, 'ref-example1', 'Example 1', 'TextDecode ( table::container ; "windows-1252" ) returns UTF-16LE-encoded text from the file in a container field that contains text with Windows character encoding.');
