INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (359, 0, 'ref-format', 'Format', 'TextEncode ( text ; encoding ; lineEndings )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (359, 1, 'ref-param', 'Parameters', 'text - any text expression or field.

encoding - the name of the character encoding to use (see below).

lineEndings - a number that specifies the line endings to use (see below).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (359, 2, 'ref-return', 'Data type returned', 'container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (359, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (359, 4, 'ref-desc', 'Description', 'For the encoding parameter, use one of the following names to specify the character encoding. If you use an empty string ("") or an unrecognized value, this function returns "?".
encoding
Encodes text using
utf-8
Unicode
iso-8859-1
Latin 1
windows-1251
Cyrillic
shift_jis
Japanese
windows-1252
Windows
gb18030
Simplified Chinese
euc-kr
Korean
big5
Traditional Chinese
macintosh
Mac Roman

For the lineEndings parameter, use one of the following values to specify the line endings to use. If you use an unrecognized value, line endings are unchanged.
lineEndings
Changes line endings to
1
Unchanged
2
Carriage return (legacy Mac standard)
3
Line feed (modern Mac, Unix/Linux standard)
4
Carriage return followed by a line feed (Windows standard)');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (359, 5, 'ref-example1', 'Example 1', 'Returns a text file as container data from a text field using Japanese character encoding and leaves line endings unchanged.

Copy

TextEncode ( table::text ; "shift_jis" ; 1 )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (359, 6, 'ref-examplen', 'Example 2', 'Converts the contents of a text field to ISO-8859-1 character encoding and Windows line endings, then exports the resulting container field as a text file.

Copy

Set Field [ table::container ; TextEncode ( table::text ; "iso-8859-1" ; 4 ) ]
Export Field Contents [ table::container ; "output.txt" ; Create folders: Off]');
