INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (362, 0, 'ref-format', 'Format', 'Furigana ( text {; option } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (362, 1, 'ref-param', 'Parameters', 'text - any text expression or text field

option - 1 through 5, depending on how you want to convert text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (362, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (362, 3, 'ref-orig', 'Originated in version', '14.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (362, 4, 'ref-desc', 'Description', 'Japanese text is composed of kana (hiragana and katakana) and kanji (characters). Kanji characters have multiple readings, and the Unicode ordering of these characters is arbitrary. Thus, to sort kanji characters in a truly meaningful way, it is necessary to sort by the kana (phonetic syllabary) reading intended for each character.

The option parameter determines whether Furigana converts the specified text to hiragana, katakana, or roman (romaji) text.
Option
Converts text to
1
Hiragana
2
Full-width katakana
3
Full-width roman (romaji)
4
Half-width katakana
5
Half-width roman (romaji)

If option is not specified or any value other than 1 through 5, Furigana returns the specified text in hiragana.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (362, 5, 'ref-example1', 'Example 1', 'Converts the specified text to hiragana.

Furigana ( "" ) returns .');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (362, 6, 'ref-examplen', 'Example 2', 'Converts the specified text to roman text.

Furigana ( "" ; 5 ) returns toukyouto.');
