INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (369, 0, 'ref-format', 'Format', 'NumToJText ( number ; separator ; characterType )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (369, 1, 'ref-param', 'Parameters', 'number - any numeric expression or field containing a number

separator - a number from 0 to 3 representing a separator

characterType - a number from 0 to 3 representing a type');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (369, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (369, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (369, 4, 'ref-desc', 'Description', 'If the value for separator and characterType are blank or other than 0 to 3, then 0 is used.

Separator:

- 0 - no separator

- 1 - every 3 digits (thousands)

- 2 - ten thousands() and millions() unit

- 3 - tens(), hundreds(), thousands(), ten thousands() and millions() unit

Type:

- 0 - half-width (hankaku) number

- 1 - full-width (zenkaku) number

- 2 - kanji number

- 3 - traditional kanji number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (369, 5, 'ref-example1', 'Example 1', 'NumToJText(123456789;2;0) returns .');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (369, 6, 'ref-examplen', 'Example 2', 'NumToJText(123456789;3;2) returns .');
