INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (372, 1, 'ref-param', 'Parameters', 'date - any calendar date

format - a number (0, 1, or 2) that describes the display format');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (372, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (372, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (372, 4, 'ref-desc', 'Description', 'If the value for format is blank or other than 0, 1, or 2, then 0 is used.

0 - 8 (Meiji 8), 8 (Taisho 8), 8 (Showa 8), 8 (Heisei 8), 8 (Reiwa 8),  (Seireki xxxx [before 1868.9.8])

1 - ()8 (Mei 8), ()8 (Tai 8), ()8 (Sho 8), ()8 (Hei 8), ()8 (Rei 8), ()xxxx (Sei xxxx [before 1868.9.8])

2 - M8, T8, S8, H8, R8, xxxx CE (before 1868.9.8)

Name of emperor in 0 = Long, 1 = Abbreviated, 2 = 2-byte roman. Seireki is returned when date is before listed emperors.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (372, 5, 'notes', 'Notes', '- YearName returns the numeric portion of an emperor year as  for the first year of a new era when the format parameter is set to 1. For example:
YearName ( DateField ; 1 ) returns  when DateField contains 5/1/2019.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (372, 6, 'ref-example1', 'Example 1', 'YearName ( DateField ; 0 ) returns  when DateField contains 7/15/2008.');
