INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (373, 0, 'ref-format', 'Format', 'JSONDeleteElement ( json ; keyOrIndexOrPath )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (373, 1, 'ref-param', 'Parameters', 'json - any text expression or field that contains a JSON object or array.

keyOrIndexOrPath - any text expression or field that specifies a JSON object name (key), an array index, or a path. See Working with the JSON functions.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (373, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (373, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (373, 4, 'ref-example1', 'Example 1', 'Deletes an element from a JSON object.

JSONDeleteElement ( "{ \"a\" : 11 , \"b\" : 12 , \"c\" : 13 }" ; "b" ) returns {"a":11,"c":13}.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (373, 5, 'ref-examplen', 'Example 2', 'Deletes an element from a nested JSON object. If the $$JSON variable is set to

Copy

{
   "a" :
   {
      "id" : 12,
      "lnk" : false
   }
}

then

Copy

JSONFormatElements (
   JSONDeleteElement ( $$JSON ; "a.lnk" )
)

returns

Copy

{
    "a" :
    {
        "id" : 12
    }
}');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (373, 6, 'related', 'Related topics', '- Functions reference

