- Using operators in formulas

- Working with the JSON functions');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (374, 0, 'ref-format', 'Format', 'JSONFormatElements ( json )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (374, 1, 'ref-param', 'Parameters', 'json - any text expression or field that contains a JSON object or array.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (374, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (374, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (374, 4, 'ref-desc', 'Description', 'This function parses the text in the json parameter. If successful, this function returns json with tab and line ending characters added and with JSON objects sorted alphabetically by key. Otherwise, this function returns "?" followed by an error message (see Handling errors in JSON data).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (374, 5, 'ref-example1', 'Example 1', 'JSONFormatElements ( "{ \"a\" : { \"lnk\" : false, \"id\" : 12 } }" ) returns

Copy

{
    "a" :
    {
        "id" : 12,
        "lnk" : false
    }
}');
