- Working with the JSON functions');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 0, 'ref-format', 'Format', 'JSONGetElement ( json ; keyOrIndexOrPath )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 1, 'ref-param', 'Parameters', 'json - any text expression or field that contains a JSON object or array.

keyOrIndexOrPath - any text expression or field that specifies a JSON object name (key), an array index, or a path. See Working with the JSON functions.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 2, 'ref-return', 'Data type returned', 'text, number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 4, 'ref-desc', 'Description', 'If the JSON value at keyOrIndexOrPath is a number or a Boolean, this function returns a number; otherwise, it returns text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 5, 'ref-example1', 'Example 1', 'JSONGetElement ( "{ \"a\" : 11, \"b\" : 22, \"c\" : 33 }" ; "b" ) returns 22 as a number.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 6, 'ref-examplen', 'Example 2', 'JSONGetElement ( "[ true, false, true ]" ; 1 ) returns 0 (false) as a number.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 7, 'ref-examplen', 'Example 3', 'JSONGetElement ( "[ 1, 2, 3, 5 ]" ; "[:]" ) returns 5 by using "[:]" to refer to the last element of the array.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 8, 'ref-examplen', 'Example 4', 'From the Example JSON data stored in the $$JSON variable, gets the value of the "name" object of the second "product" object in the array.

JSONGetElement ( $$JSON ; "bakery.product[1]name" ) returns Chocolate Cake as text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 9, 'ref-examplen', 'Example 5', 'If the $$JSON variable is set to

Copy

{
    "bakery" :
    {
        "product" :
        [
            {
                "product.id" : "FB1",
                "product.name" : "Donuts",
                "price": 1.99,
                "stock" : 43,
                "product.category" : "Breads",
                "special" : true
            }
        ]
    }
}

then JSONGetElement ( $$JSON ; "[''bakery''][''product''][0][''product.name'']" ) returns Donuts as text, which is the value of the "product.name" key in the first "product" object in the array. Because the key name includes a period, the keyOrIndexOrPath parameter is written in bracket notation.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (375, 10, 'related', 'Related topics', '-
