INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (376, 0, 'ref-format', 'Format', 'JSONGetElementType ( json ; keyOrIndexOrPath )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (376, 1, 'ref-param', 'Parameters', 'json - any text expression or field that contains a JSON object or array.

keyOrIndexOrPath - any text expression or field that specifies a JSON object name (key), an array index, or a path. See Working with the JSON functions.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (376, 2, 'ref-return', 'Data type returned', 'text, number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (376, 3, 'ref-orig', 'Originated in version', '19.5');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (376, 4, 'ref-desc', 'Description', 'If the JSON value at keyOrIndexOrPath is valid, this function returns the data type of that value returned as a number; otherwise, it returns an error text message. The data type numbers also have named values of JSONString, JSONNumber, JSONObject, JSONArray, JSONBoolean, and JSONNull. The JSONRaw data type value will never be returned. See JSONSetElement for more information about these data types.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (376, 5, 'ref-example1', 'Example 1', 'Validates that the text is a valid JSON object.

(JSONGetElementType( "{ \"a\" : 11 }"; "" ) = JSONObject) returns 1 (true) as a number.

(JSONGetElementType( "{ a : 11 }"; "" ) = JSONObject) returns 0 (false) as a number.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (376, 6, 'ref-examplen', 'Example 2', 'Returns the type of a specific JSON element.

JSONGetElementType( "{ \"a\" : 11 , \"b\" : false }"; "b" ) returns 5 (JSONBoolean) as a number.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (376, 7, 'ref-examplen', 'Example 3', 'Checks JSON data for an element type that is invalid.

JSONGetElementType( "[100, 200]"; "3" ) returns "? Incorrect key, index, or path" as a string.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (376, 8, 'related', 'Related topics', '-
