INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (377, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (377, 3, 'ref-orig', 'Originated in version', '16.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (377, 4, 'notes', 'Notes', '- Each returned value, except the last, ends with a carriage return.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (377, 5, 'ref-example1', 'Example 1', 'Gets the names of all objects at the root of the JSON object.

JSONListKeys( "{ \"a\" : 11, \"b\" : 22, \"c\" : 33 }" ; "" ) returns a¶b¶c.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (377, 6, 'ref-examplen', 'Example 2', 'From the Example JSON data stored in the $$JSON variable, gets the indexes of all elements in the array in the "product" object.

JSONListKeys ( $$JSON ; "bakery.product" ) returns 0¶1¶2.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (377, 7, 'ref-examplen', 'Example 3', 'From the Example JSON data stored in the $$JSON variable, gets the keys of all elements in the first "product" object in the array.

JSONListKeys ( $$JSON ; "bakery.product[0]" ) returns category¶id¶name¶price¶special¶stock.');
