INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (378, 4, 'notes', 'Notes', '- Each returned value, except the last, ends with a carriage return.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (378, 5, 'ref-example1', 'Example 1', 'Gets the values of all objects at the root of the JSON object.

JSONListValues( "{ \"a\" : 11, \"b\" : 22, \"c\" : 33 }" ; "" ) returns 11¶22¶33.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (378, 6, 'ref-examplen', 'Example 2', 'From the Example JSON data stored in the $$JSON variable, gets the values of all elements in the array in the "product" object.

JSONListValues ( $$JSON ; "bakery.product" ) returns

{"category":"Breads","id":"FB1","name":"Donuts","price":1.99,"special":true,"stock":43}
{"category":"Cakes","id":"FB2","name":"Chocolate Cake","price":22.5,"special":true,"stock":23}
{"category":"Breads","id":"FB3","name":"Baguette","price":3.95,"special":true,"stock":34}');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (378, 7, 'ref-examplen', 'Example 3', 'From the Example JSON data stored in the $$JSON variable, gets the values of all elements in the first "product" object in the array.

JSONListValues ( $$JSON ; "bakery.product[0]" ) returns
Breads¶FB1¶Donuts¶1.99¶1¶43.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (378, 8, 'related', 'Related topics', '- Functions reference

