INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (379, 0, 'ref-format', 'Format', 'JSONMakeArray ( listOfValues ; separator ; type )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (379, 1, 'ref-param', 'Parameters', 'listOfValues - a list of separated values.

separator - text that separates one value from the next (an empty string means any line separator).

type - a numeric value that specifies the type of data in the array. Use the same numeric values as for the type parameter in the JSONSetElement function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (379, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (379, 3, 'ref-orig', 'Originated in version', '21.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (379, 4, 'ref-desc', 'Description', 'For listOfValues, this function returns a JSON array of values. Each value must be separated by the character you specify in the separator parameter.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (379, 5, 'notes', 'Notes', '-
If separator is an empty string, then listOfValues can be separated by any line separator (carriage return, line feed, or other Unicode line or paragraph separator characters).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (379, 6, 'ref-example1', 'Example 1', 'JSONMakeArray ( "34,600,18,600,18.0" ; "," ; JSONNumber ) returns:

Copy

[34,600,18,600,18]');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (379, 7, 'ref-examplen', 'Example 2', 'When the Product::Colors field contains

Copy

green
red
yellow

JSONMakeArray ( Product::Colors ; "" ; JSONString ) returns:

Copy

["green","red","yellow"]');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (379, 8, 'ref-examplen', 'Example 3', 'When the Bakery::Product field contains

Copy

{"id" : "FB1", "name" : "Donuts" } #
1.99 #
true #
null #
"Breads"

then

Copy

JSONFormatElements (
    JSONMakeArray ( Bakery::Product ; "#" ; JSONRaw )
)

returns

Copy

[
    {
        "id" : "FB1",
        "name" : "Donuts"
    },
    1.99,
    true,
    null,
    "Breads"
]');
