INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (387, 0, 'ref-format', 'Format', 'Min ( field {; field...} )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (387, 1, 'ref-param', 'Parameters', 'field - any related field, repeating field, or set of non-repeating fields; or an expression that returns a field, repeating field, or set of non-repeating fields.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (387, 2, 'ref-return', 'Data type returned', 'text, number, date, time, timestamp');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (387, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (387, 4, 'ref-desc', 'Description', 'Field can be any of the following:

- a repeating field (repeatingField).

- a field in matching related records specified by (table::field), whether or not these records appear in a portal.

- several non-repeating fields in a record (field1;field2;field3...).

- corresponding repetitions of repeating fields in a record (repeatingField1;repeatingField2;repeatingField3), if the result is returned in a repeating field with at least the same number of repeats.

- several fields in the first matching record specified by (table::field1;table::field2;...). You can include fields from different tables (table 1::field A;table 2::field B...).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (387, 5, 'notes', 'Notes', '- When a referenced field is a repeating field, the Min function returns the minimum value in the first repetition field, then the minimum value in the second repetition field, and so on.

- If the parameters are of different data types, the Min and Max functions convert all parameters to numbers before comparing them. If all parameters are text, these functions compare the parameters as text.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (387, 6, 'ref-example1', 'Example 1', 'A Contracts table has a portal showing bids submitted for each contract.

Min(Bids::Price) returns the lowest bid submitted for a contract.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (387, 7, 'ref-examplen', 'Example 2', 'In the following examples:

- Field1 contains two repetitions with values of 1 and 2.

- Field2 contains four repetitions with values of 5, 6, 7, and 8.

- Field3 contains 6.

Min(Field2) returns 5 when the calculation isn''t a repeating field.

Min(Field1;Field2;Field3) returns 1, 2, 7, 8 when the calculation is a repeating field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (387, 8, 'related', 'Related topics', '- Functions reference

