INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (391, 0, 'ref-format', 'Format', 'Variance ( field {; field...} )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (391, 1, 'ref-param', 'Parameters', 'field - any related field, repeating field, or set of non-repeating fields; or an expression that returns a field, repeating field, or set of non-repeating fields.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (391, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (391, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (391, 4, 'ref-desc', 'Description', 'The variance of a distribution is a measure of how spread out the distribution is. Field can be any of the following:

- a repeating field (repeatingField).

- a field in matching related records specified by (table::field), whether or not these records appear in a portal.

- several non-repeating fields in a record (field1;field2;field3...).

- corresponding repetitions of repeating fields in a record (repeatingField1;repeatingField2;repeatingField3), if the result is returned in a repeating field with at least the same number of repeats.

- several fields in the first matching record specified by (table::field1;table::field2;...). You can include fields from different tables (table 1::field A;table 2::field B...).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (391, 5, 'ref-example1', 'Example 1', 'A portal displays the related values 5, 6, 7, and 8 in Scores.

Variance(table::Scores) returns 1.66666666....');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (391, 6, 'ref-examplen', 'Example 2', 'In the following examples:

- Field1 contains two repetitions with values of 1 and 2.

- Field2 contains four repetitions with values of 5, 6, 7, and 8.

- Field3 contains four repetitions with values of 6, 0, 4,and 4.

- Field4 contains one repetition with a value of 3.

Variance(Field4) results in an error since the variance of a single value is not defined.

Variance(Field1;Field2;Field3) returns 7, 9.33333333..., 4.5, 8 if the calculation is a repeating field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (391, 7, 'ref-examplen', 'Example 3', 'Two classes of students take an exam. Class 1 has scores of 70, 71, 70, 74, 75, 73, 72 and Class 2 has scores of 55, 80, 75, 40, 65, 50, 95. The variance for each class is:

Class 1: 3.80952380...

Class 2: 361.90476190...

The variance for Class 1 is much lower than the variance for Class 2, because the scores for Class 2 are more spread out.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (391, 8, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (392, 0, 'ref-format', 'Format', 'VarianceP ( field {; field...} )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (392, 1, 'ref-param', 'Parameters', 'field - any related field, repeating field, or set of non-repeating fields; or an expression that returns a field, repeating field, or set of non-repeating fields.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (392, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (392, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (392, 4, 'ref-desc', 'Description', 'The variance of a population distribution is a measure of how spread out the distribution is. Field can be any of the following:

- a repeating field (repeatingField).

- a field in matching related records specified by (table::field), whether or not these records appear in a portal.

- several non-repeating fields in a record (field1;field2;field3...).

- corresponding repetitions of repeating fields in a record (repeatingField1;repeatingField2;repeatingField3), if the result is returned in a repeating field with at least the same number of repeats.

- several fields in the first matching record specified by (table::field1;table::field2;...). You can include fields from different tables (table 1::field A;table 2::field B...).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (392, 5, 'ref-example1', 'Example 1', 'A portal displays the related values 5, 6, 7, and 8 in Scores.

VarianceP(table::Scores) returns 1.25.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (392, 6, 'ref-examplen', 'Example 2', 'In the following examples:

- Field1 contains two repetitions with values of 1 and 2.

- Field2 contains four repetitions with values of 5, 6, 7, and 8.

- Field3 contains four repetitions with values of 6, 0, 4, and 4.

- Field4 contains one repetition with a value of 3.

VarianceP(Field4) results in an error since the variance of a single value is not defined.

VarianceP(Field1;Field2;Field3) returns 4.66666666..., 6.22222222..., 2.25, 4 if the calculation is a repeating field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (392, 7, 'ref-examplen', 'Example 3', 'Two classes of students take an exam. Class 1 has scores of 70, 71, 70, 74, 75, 73, 72 and Class 2 has scores of 55, 80, 75, 40, 65, 50, 95. The population variance for each class is:

Class 1: 3.26530612...

Class 2: 310.20408163...

The population variance for Class 1 is much lower than the population variance for Class 2 because the scores for Class 1 are more tightly clustered.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (392, 8, 'related', 'Related topics', '- Functions reference

- About formulas

