INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (409, 0, 'ref-format', 'Format', 'Case ( test1 ; result1 {; test2 ; result2 ; ... ; defaultResult } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (409, 1, 'ref-param', 'Parameters', 'test - any text or numeric expression.

result - result corresponding to the expression.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (409, 2, 'ref-return', 'Data type returned', 'text, number, date, time, timestamp, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (409, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (409, 4, 'ref-desc', 'Description', 'The Case function evaluates each test expression in order, and when a True expression is found, returns the value specified in result for that expression.

You can include a default result at the end of the parameter list. If none of the expressions evaluated return True, the Case function returns the value specified for defaultResult. If no default result is supplied, Case returns an empty result.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (409, 5, 'ref-example1', 'Example 1', 'Case ( Score >= 90 ; "Excellent" ; Score > 50 ; "Satisfactory" ; "Needs Improvement" ) displays Excellent when the score is 90 or above, Satisfactory when the score is between 50 and 90, and Needs Improvement for any other score.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (409, 6, 'ref-examplen', 'Example 2', 'Case ( Shipment Method="Ground" ; 2 ; Shipment Method="Air" ; 10) returns 2 when the Shipment Method field contains Ground, and returns 10 when the Shipment Method field contains Air.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (409, 7, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (410, 0, 'ref-format', 'Format', 'Choose ( test ; result0 {; result1 ; result2...} )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (410, 1, 'ref-param', 'Parameters', 'test - Any integer calculation. The calculation result of test must be a number that indexes into the list that follows. Because the index is a 0-based index, the test result must be 0 to access the first result.

result - one or more results.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (410, 2, 'ref-return', 'Data type returned', 'text, number, date, time, timestamp, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (410, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (410, 4, 'ref-desc', 'Description', 'FileMaker Pro evaluates test to obtain an index number, which is used to choose the corresponding ordinal result.

Because the Choose function is a 0-based list, the first item on the list is indexed 0 and the second item on the list is indexed 1. For example, if test evaluates to 2, then result2 is chosen.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (410, 5, 'ref-example1', 'Example 1', 'Copy

Choose ( Rating ; "Not Applicable" ; "Good" ; "Fair" ; "Poor" )

Rating is a number field that is empty or holds a value. If Rating is empty or 0, the Choose function returns Not Applicable. If Rating is 1, the result is Good. If Rating is 2, the result is Fair, and if it is 3, the result is Poor. If Rating contains a value that does not map to one of the result parameters, the Choose function returns nothing.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (410, 6, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 0, 'ref-format', 'Format', 'Evaluate ( expression {; [field1 ; field2 ;...]} )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 1, 'ref-param', 'Parameters', 'expression - any text expression or text field.

fields - a list of fields that this function is dependent on. When these fields are modified, the calculation will update its result.

Parameters in braces { } are optional. Notice that the optional field list is enclosed in brackets [ ].');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 2, 'ref-return', 'Data type returned', 'text, number, date, time, timestamp, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 4, 'ref-desc', 'Description', 'The optional fields parameter is a list of fields this calculation is dependent on. If a necessary field isn''t listed, modifying that dependent field won''t update the result of the calculation.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 5, 'notes', 'Notes', '- If a server-side script contains the Evaluate function, use English function names in Evaluate''s calculation. Evaluate does not recognize localized function names when it is evaluated in a server-side script. See About running scripts on FileMaker Server and FileMaker Cloud.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 6, 'ref-example1', 'Example 1', 'Evaluate(TextField) returns 4 when TextField contains 2 + 2.

Evaluate("textfield") returns 2 + 2 when textfield contains 2 + 2.

Evaluate(GetField("textfield")) returns 4 when textfield contains 2 + 2.

Evaluate(TextField;[Amount]) returns .80 when TextField contains .08 * Amount and the Amount field contains 10.00.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 7, 'ref-examplen', 'Example 2', 'Evaluate( "Let ( TaxRate = .05 ;" & Tax Rate Calculation & ")" ) returns .50 when the field Tax Rate Calculation contains SubTotal * TaxRate where SubTotal is a numeric field that contains 10.00.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 8, 'ref-examplen', 'Example 3', 'The following example shows how to pass named parameters using the Evaluate, Let, and Get(ScriptParameter) functions, allowing access only to variable "a" (the example returns 6):

Copy

ScriptParameter = "a = 5; b = 10"

Copy

Evaluate("Let ( [" & Get(ScriptParameter) & "]; a + 1 )")');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 9, 'ref-examplen', 'Example 4', 'The following example shows how to pass named parameters, allowing access to both variable "a" and "b". The simplified first parameter makes the second parameter more complex (the example returns 6, 12):

Copy

ScriptParameter = "a = 5; b = 10"

Copy

Evaluate("Let ( [" & Get(ScriptParameter) & "]; a + 1 & \", \" & b + 2 )")');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 10, 'ref-examplen', 'Example 5', 'The following example shows how to pass named parameters, while keeping the ability to check the syntax of the second parameter of the Let function (the example returns 6, 12):

Copy

ScriptParameter = "a = 5; b = 10"

Copy

Let(  [a = Evaluate("Let( [" & Get(ScriptParameter) & "]; a )"),
            b = Evaluate("Let( [" & Get(ScriptParameter) & "]; b )")]; a + 1 & ", " & b + 2 )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 11, 'ref-examplen', 'Example 6', 'The Evaluate function evaluates an expression, including field values to be evaluated as a calculation formula. It also allows you to specify field dependencies so that a calculation using the evaluation function can be triggered due to changes in other fields of the same record. This function evaluates user-defined formulas. For example, you can create a formula in the Total field that computes state tax:

Copy

Evaluate(StateTaxFormula) + ShippingCost

where the StateTaxFormula field contains:

Copy

SubTotal * 1.0875

and the SubTotal field contains the subtotal before tax and shipping.

The Evaluate function has an optional second parameter, which is a field the calculation is dependent on. When the dependent field contents change, FileMaker Pro reevaluates the calculation. In the following example, the Total calculation will be reevaluated when SubTotal changes:

Copy

Evaluate(StateTaxFormula; SubTotal) + ShippingCost

The dependent parameter can also be useful in other cases. For example,

Copy

Evaluate ( "Get ( CurrentTimeStamp )" ; [ FieldB ; FieldC ] )

will store a timestamp in the calculation field whenever FieldB or FieldC changes.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (411, 12, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (412, 0, 'ref-format', 'Format', 'EvaluationError ( expression )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (412, 1, 'ref-param', 'Parameters', 'expression - any calculation expression');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (412, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (412, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (412, 4, 'ref-desc', 'Description', 'There are two types of errors: syntax and runtime. A syntax error indicates an invalid calculation. A runtime error, such as Field missing or Record missing, occurs when the calculation currently being run is valid but cannot properly execute. See FileMaker error codes for a list of error codes and messages.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (412, 5, 'notes', 'Notes', '- The EvaluationError function must enclose the Evaluate function to return any syntax errors.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (412, 6, 'ref-example1', 'Example 1', 'EvaluationError( GetField ( "total" ) + 1 ) returns 102 (Field Missing) when the field total has been deleted or renamed.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (412, 7, 'ref-examplen', 'Example 2', 'EvaluationError( Evaluate ( calculationField ) ) returns 1207 (Unbalanced Parenthesis) when calculationField contains abs(-1 with no closing parenthesis.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (412, 8, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (413, 0, 'ref-format', 'Format', 'ExecuteSQL ( sqlQuery ; fieldSeparator ; rowSeparator { ; arguments... } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (413, 1, 'ref-param', 'Parameters', 'sqlQuery - an SQL SELECT statement. The statement can include a Union clause that combines the results of two queries. The statement can contain programmatically generated SQL (dynamic parameters) that indicate where optional arguments are to be used in the query. Use the question mark character (?) to specify a dynamic parameter.

fieldSeparator - the character string used as a separator between fields in the result. If an empty string is specified, the separator is a comma. The field separator is not displayed after the last field in the result.

rowSeparator - the character string used as a separator between records in the result. If an empty string is specified, the separator is a carriage return. The row separator is not displayed after the last row in the result.

arguments - one or more expressions separated by semicolons (;) that are evaluated and used as values for the dynamic parameters in the query statement.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (413, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (413, 3, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (413, 4, 'ref-desc', 'Description', 'ExecuteSQL enables you to execute SQL SELECT statements containing dynamic parameters to safely query FileMaker Pro databases in order to avoid security vulnerabilities through injection attacks.

ExecuteSQL does not recognize relationships created in FileMaker Pro, which gives you flexibility to define relationships in SQL statements and retrieve data from any table, independent of the layout context.

ExecuteSQL cannot be used with SQL statements that modify data or the database schema (such as the Insert Into or Delete Table commands).

When you use multiple dynamic parameters in sqlQuery, the first question mark character is replaced by the first arguments parameter, the second by the second, and so on.

If an error occurs during query parsing or execution, ExecuteSQL returns ?. To receive more detailed error information, use ExecuteSQL in the Data Viewer, or use the ExecuteSQLe function. See FileMaker SQL error codes in the FileMaker SQL Reference.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (413, 5, 'notes', 'Notes', '-
To apply the correct formatting to dates in an SQL query, use the DATE statement. If you do not use the DATE statement, ExecuteSQL treats dates as literal strings.

-
FileMaker Pro returns date, time, and number data in Unicode/SQL format, not in the locale of the operating system or the file.

-
ExecuteSQL accepts only the SQL-92 syntax ISO date and time formats with no braces. ExecuteSQL does not accept the ODBC/JDBC format date, time, and timestamp constants in braces.

-
FileMaker SQL uses the Unicode binary sort order, which is different from the FileMaker Pro sort order used with language sorting or with the default language-neutral sort order.

-
For details about supported SELECT statement syntax, see FileMaker SQL Reference.

-
The ExecuteSQL function uses SQL SELECT statements to query tables in FileMaker data sources, not ODBC data sources. To execute SELECT and other supported SQL statements against ODBC data sources, use the Execute SQL script step.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (413, 6, 'ref-example1', 'Example 1', 'Suppose a database contains two tables, Employees and Salaries, which are related through the EmpID field.

Note The Employees::EmpID, Salaries::EmpID, and Salaries::Salary fields are number fields.

You can use the ExecuteSQL function to return a field value from a specific record without changing the current record or modifying the found set.

ExecuteSQL ( "SELECT Department FROM Employees WHERE EmpID = 1"; ""; "" ) returns Development regardless of the current record, found set, or layout.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (413, 7, 'ref-examplen', 'Example 2', 'From the Employees table in Example 1, this expression returns the EmpID and Last Name values of the employees in the Development department:

ExecuteSQL ( "SELECT EmpID, \"Last Name\" FROM Employees WHERE Department = ''Development''" ; "," ; ¶ )

The result is returned with a comma separating each field value and a carriage return separating the records:

Copy

1,Smith
2,Ogawa');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (413, 8, 'ref-examplen', 'Example 3', 'From Example 1, suppose you want to add a field to the Employees table to display the percentage of an employee''s salary relative to the total salaries in a department. Though you could use a calculation in FileMaker Pro to generate this value, you can use the ExecuteSQL function to specify this query using dynamic parameters. The example below uses table aliases for the Employees table (E) and the Salaries table (S) when specifying fields (S.Salary, E.EmpID, and S.EmpID).

Define a calculation field (Percent Dept Salaries) in the Employees table, then use the ExecuteSQL function to specify a query statement in the following calculation:

Copy

Round (
   100 * Salaries::Salary / ExecuteSQL (
      "SELECT SUM (S.Salary)
      FROM Employees E
      JOIN Salaries S
      ON E.EmpID = S.EmpID
      WHERE E.Department = ?";
      ""; ""; Employees::Department
   ) ;
2 )

Note Because this calculation needs to get the employee''s salary from the Salaries table (Salaries::Salary), you must create a relationship between the Employees::EmpID and Salaries::EmpID fields in the relationships graph (see Creating and changing relationships). In contrast, the ExecuteSQL function doesn''t use the relationships graph. So in this example, the JOIN clause establishes the relationship used by the SELECT statement in ExecuteSQL.

For each employee record, the Percent Dept Salaries field calculates the percentage of the employee''s salary relative to the sum of the salaries for the employee''s department.
Employees
EmpID  | Last Name  | Department  | Percent Dept Salaries
1  | Smith  | Development  | 52.97
2  | Ogawa  | Development  | 47.03
3  | Durand  | Quality  | 48.86
4  | Garcia  | Quality  | 51.14
5  | Mehmet  | Documentation  | 100
6  | Ferrini  | Marketing  | 100');
