INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (414, 0, 'ref-format', 'Format', 'ExecuteSQLe ( sqlQuery ; fieldSeparator ; rowSeparator { ; arguments... } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (414, 1, 'ref-param', 'Parameters', 'See ExecuteSQL function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (414, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (414, 3, 'ref-orig', 'Originated in version', '21.1');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (414, 4, 'ref-desc', 'Description', 'ExecuteSQLe is identical to the ExecuteSQL function, except that, if an error occurs during query parsing or execution, ExecuteSQLe returns an error in this format:

? ERROR: FQLxxxx/(line:offset): message

For possible error codes and messages, see FileMaker SQL error codes.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (414, 5, 'notes', 'Notes', '-
For details about supported SELECT statement syntax, see FileMaker SQL Reference.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (414, 6, 'ref-example1', 'Example 1', 'Starting with Example 1 for ExecuteSQL, change the calculation to use the ExecuteSQLe function. Then, to see a detailed error message, change the query so it refers to a nonexistent field named Title:

Copy

ExecuteSQLe ( "SELECT Title FROM Employees WHERE EmpID = 1"; ""; "" )

This returns:

? ERROR: FQL0007/(1:7): The column named "Title" does not exist in any table in the column reference''s scope.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (414, 7, 'ref-examplen', 'Example 2', 'Sets a variable to the result of the query in Example 1, then checks whether the result begins with ?. If it does, it displays the rest of the result (the error message) and exits the script.

Copy

Set Variable [ $result ; Value: ExecuteSQLe ( "SELECT Title FROM Employees WHERE EmpID = 1"; ""; "" ) ]
If [ Left ( $result ; 1 ) = "?" ]
    Show Custom Dialog [ Right ( $result ; Length ( $result ) - 2 ) ]
    Exit Script [ Text Result: "error" ]
End If');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (414, 8, 'related', 'Related topics', '- Functions reference

