INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (415, 0, 'ref-format', 'Format', 'GetAsBoolean ( data )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (415, 1, 'ref-param', 'Parameters', 'data - any text, number, date, time, timestamp or container expression, or a field containing text, a number, date, time, timestamp or container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (415, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (415, 3, 'ref-orig', 'Originated in version', '8.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (415, 4, 'ref-desc', 'Description', 'Returns a Boolean value.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (415, 5, 'notes', 'Notes', '- When an expression results in an error, it returns "?." GetAsBoolean evaluates "?" as 1 (true).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (415, 6, 'ref-example1', 'Example 1', 'GetAsBoolean ( "" ) returns 0.

GetAsBoolean ( "Some text here." ) returns 0.

GetAsBoolean ( Container Field ) returns 1 when the field named Container Field contains data, or returns 0 when Container Field is empty.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (415, 7, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields
Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (416, 0, 'ref-format', 'Format', 'GetField ( fieldName )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (416, 1, 'ref-param', 'Parameters', 'fieldName - any text expression or text field that refers to a field''s name');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (416, 2, 'ref-return', 'Data type returned', 'text, number, date, time, timestamp, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (416, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (416, 4, 'ref-desc', 'Description', 'GetField evaluates fieldName, matches the result to a field in the table on which the calculation was performed, and returns the contents of that field.

To return values of fields that have the same field name across multiple tables, enclose fieldName in double quotation marks, as in GetField("fieldName").

For example, GetField("Phone") returns a value from Customer::Phone when GetField is calculated on the Customer table, and returns Company::Phone when GetField is calculated on the Company table.

To return the values of multiple fields, do not enclose fieldName in quotation marks, as in GetField(fieldName), and specify a field that contains a value that matches the name of another field in the table. To change the value that GetField returns, change the value in the specified field to match the name of a different field in the table.

For example, a table has three fields: Customer::ContactMethod, Customer::Phone, and Customer::Email. When Customer::ContactMethod contains "Phone", GetField(ContactMethod) returns the contents of Customer::Phone. However, when Customer::ContactMethod contains "Email", GetField(ContactMethod) returns the contents of Customer::Email.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (416, 5, 'ref-example1', 'Example 1', 'If you sort records on a calculation field that''s defined by the GetField function, you can dynamically sort records and display subsummary data by changing the value of the field specified by GetField.

Suppose a database has four fields:

- Customer Name, a text field

- City, a text field

- SortSelection, a global field

- SortKey, a calculation field that''s defined as GetField(SortSelection)

This script goes to the Invoices layout and sorts records on the SortKey field:

Copy

Go to Layout ["Invoices" (Invoices)]
Sort Records [Restore; With dialog: Off]
#Sort by the SortKey field
Go to Record/Request/Page [First]

If SortSelection contains "Customer Name", SortKey returns the values of the Customer Name field, and the found set is sorted by Customer Name. Any subsummary data specified to appear when records are sorted by SortKey is displayed from the Customer Name field.

If SortSelection is changed to contain "City", SortKey returns the values of the City field, the found set is re-sorted by City, and subsummary data is displayed from the City field.

Because the found set is sorted by SortKey, the sort information is automatically updated when the values returned by SortKey change, and you do not have to perform another sort operation.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (416, 6, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (417, 0, 'ref-format', 'Format', 'GetNthRecord ( field ; recordNumber )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (417, 1, 'ref-param', 'Parameters', 'field - any related field or repeating field, or an expression that returns a field or a repeating field

recordNumber - the record number from which you want data');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (417, 2, 'ref-return', 'Data type returned', 'text, number, date, time, timestamp, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (417, 3, 'ref-orig', 'Originated in version', '8.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (417, 4, 'ref-desc', 'Description', 'The result of GetNthRecord() will not be updated when the record referred to by GetNthRecord() is a record other than the one in which the calculation is currently being evaluated.

GetNthRecord of the current table returns the Nth record of the found set according to how the current table is sorted.

GetNthRecord of a related table returns the Nth record of the related set (relative to the current record), based on the sort order of the relationship.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (417, 5, 'ref-example1', 'Example 1', 'GetNthRecord(First Name;2) returns the contents of the First Name field for record 2 in the current table.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (417, 6, 'ref-examplen', 'Example 2', 'GetNthRecord(First Name;Get(RecordNumber)+ 1) returns the contents of the First Name field for the next record in the current table.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (417, 7, 'ref-examplen', 'Example 3', 'GetNthRecord(Contacts::First Name;2) returns the contents of the First Name field for record 2 in the Contacts table.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (417, 8, 'ref-examplen', 'Example 4', 'GetNthRecord(Contacts::Has Repetitions[2];2) returns the contents of the second repetition of the Has Repetitions field for record 2 in the Contacts table.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (417, 9, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas

- Sorting records');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (418, 0, 'ref-format', 'Format', 'GetSummary ( summaryField ; breakField )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (418, 1, 'ref-param', 'Parameters', 'summaryField - field of type summary, or an expression that returns a reference to one.

breakField - field, or an expression that returns a reference to one. To calculate a grand summary value, use the same summary field for both the summary field and the break field parameters.

GetSummary must be set up in the same table as the break field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (418, 2, 'ref-return', 'Data type returned', 'number, date, time, timestamp');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (418, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (418, 4, 'ref-desc', 'Description', 'This function produces subsummary values. If the file isn''t sorted by the break field, the result is blank.

When a summary field is also used as the break field, returns the summary field value for the entire found set of records (a grand summary value).

Use GetSummary to capture summary values when you want to:

- use summary values in a calculation

- display subsummary values in Browse mode or in a body part

Calculations using the GetSummary function are unstored.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (418, 5, 'notes', 'Notes', '- You can get similar results using a self-join relationship and Aggregate functions. For more information, see Working with related data in portals.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (418, 6, 'ref-example1', 'Example 1', 'GetSummary(Total Sales;Country) returns a summary of all records pertaining to the value in the Country field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (418, 7, 'ref-examplen', 'Example 2', 'GetSummary(Total Sales;Total Sales) produces a summary of all records (similar to using a summary field, which is a total of total sales).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (418, 8, 'ref-examplen', 'Example 3', 'If(ThisCharge > 3 * GetSummary(AvgCharge;Customer), "Verify this charge", " ") displays Verify this charge if the current charge is greater than three times the average charge.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (418, 9, 'ref-examplen', 'Example 4', 'GetSummary(Total Sales, if(Number of Countries > 1, Country, Sales Zone)) returns a summary of Total Sales by Country if Number of Countries is greater than 1. Otherwise, it returns a summary of Total Sales by Sales Zone.');
