INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (419, 0, 'ref-format', 'Format', 'If ( test ; result1 {; result2 } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (419, 1, 'ref-param', 'Parameters', 'test - any numeric value or logical expression

result1 - expression or field name

result2 - expression or field name

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (419, 2, 'ref-return', 'Data type returned', 'text, number, date, time, timestamp, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (419, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (419, 4, 'ref-desc', 'Description', 'If test is True (any non-zero numeric result), FileMaker Pro returns result1. If test is False (0), result2 is returned. If test is False, and no result2 is supplied, If returns an empty result. Test must be an expression that returns either a numeric or Boolean (True, False) result.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (419, 5, 'notes', 'Notes', '- If you have more than two possible results, consider using the Case function.

- By default, if test refers to a field that doesn''t yet contain a value, If returns an empty result. To override this functionality, deselect the Do not evaluate if all referenced fields are empty checkbox.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (419, 6, 'ref-example1', 'Example 1', 'If ( Country = "USA" ; "US Tech Support" ; "International Tech Support" ) returns International Tech Support, if the Country field contains France or Japan. Returns US Tech Support if the Country field contains USA.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (419, 7, 'ref-examplen', 'Example 2', 'If ( State = "CA" ; Subtotal * CA Tax Rate ; 0 ) returns the tax if the purchaser is a resident of California; otherwise returns 0.');
