- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (420, 0, 'ref-format', 'Format', 'IsEmpty ( field )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (420, 1, 'ref-param', 'Parameters', 'field - any field name, text expression, or numeric expression');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (420, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (420, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (420, 4, 'ref-desc', 'Description', 'This function returns 1 (true) if a field is empty, if a related field, a related table, relationship, or a file is missing, or if another error occurs; otherwise, 0 (false).

For container fields, this function returns 0 (false) if the field contains a file. To determine whether a file in a container field is empty, use the GetContainerAttribute function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (420, 5, 'ref-example1', 'Example 1', 'IsEmpty ( OrderNum ) returns 1 if the OrderNum field is empty.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (420, 6, 'ref-examplen', 'Example 2', 'If ( IsEmpty ( LastName ) ; "Invalid record" ; "" ) displays Invalid Record if the LastName field is blank, but displays nothing if there is an entry in LastName.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (420, 7, 'ref-examplen', 'Example 3', 'IsEmpty ( Payments::DatePaid ) returns 1 if, for example, the Payments table has been moved or renamed.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (420, 8, 'ref-examplen', 'Example 4', 'IsEmpty ( "text" ) returns 0.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (420, 9, 'related', 'Related topics', '- Functions reference

