INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (422, 5, 'ref-examplen', 'Example 2', 'IsValidExpression(calculationField) returns 0 (false) if calculationField contains abs(-1 with no closing parenthesis.');
