INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (426, 0, 'ref-format', 'Format', 'Self');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (426, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (426, 2, 'ref-return', 'Data type returned', 'text, number, date, time, timestamp');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (426, 3, 'ref-orig', 'Originated in version', '9.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (426, 4, 'ref-desc', 'Description', 'The Self function provides a way for a calculation to reference the content of the object with which it is associated without having to explicitly reference the object. With Self, you can create a single calculation formula that can be applied to different objects.

The Self function can only be used in conditional formatting, tooltips, placeholder text, the Hide object when Inspector option, the Title and Help Accessibility Inspector options, and field definition calculations (including auto-enter and validation calculations).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (426, 5, 'ref-example1', 'Example 1', 'This example formula can be used in an object''s conditional formatting panel to set text formatting when the number entered in the field is greater than 10.

self > 10 returns 1 (True) when applied to a layout field object whose value is greater than 10.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (426, 6, 'ref-examplen', 'Example 2', 'Use the following example in a layout object''s tooltip calculation to display different tooltip text according to whether or not a value less than zero was entered.

Copy

if ( self < 0 ; "Value is less than zero" ; "Value is zero or greater" )');
