INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (433, 3, 'ref-orig', 'Originated in version', '21.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (433, 4, 'ref-desc', 'Description', 'The GetEmbeddingAsFile and GetEmbeddingAsText functions convert embedding vectors between text (a JSON array) and binary container data. They may be useful for exporting vectors for use outside of a FileMaker Pro file or for importing them into a FileMaker Pro file.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (433, 5, 'ref-example1', 'Example 1', 'Converts the embedding vector in the Meetings::Note_Embedding_JSON text field into binary data and stores it as a file in the Meetings::Note_Embedding container field with the specified filename.

Copy

Set Field [ Meetings::Note_Embedding ; GetEmbeddingAsFile ( Meetings::Note_Embedding_JSON ; "embedding_from_FileMaker.fve" ) ]');
