INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (437, 0, 'ref-format', 'Format', 'GetRAGSpaceInfo ( ragAccountName {; spaceID } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (437, 1, 'ref-param', 'Parameters', 'ragAccountName - a text expression for the name of the RAG account to use. In the current file, use the Configure RAG Account script step to set up the account and assign it this name any time before this function is used.

spaceID - ID of a RAG space. If omitted, returns information about all RAG spaces for the specified account.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (437, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (437, 3, 'ref-orig', 'Originated in version', '22.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (437, 4, 'ref-desc', 'Description', 'GetRAGSpaceInfo returns information about retrieval-augmented generation (RAG) spaces on the AI model server specified by ragAccountName. You can use it to verify the existence of a RAG space, monitor its content, and audit RAG operations.

If no spaceID value is specified, the function returns a JSON object containing an array of RAG spaces available to the specified RAG account:

Copy

{
  "rag_space_list": [
    {
      "space_id": "<string>",
      "model": "<string>"
    }
  ]
}

-
rag_space_list is an array of RAG spaces.

-
space_id is the key for a RAG space ID.

-
model is the key for the name of the model used to generate text embedding vectors in this RAG space.

If a spaceID value is specified, the function returns a JSON object containing information about the RAG space and the data in it:

Copy

{
  "rag_space_id": "<string>",
  "model": "<string>",
  "entries": <number>,
  "values": [
    {
      "id": "<string>" or <number>,
      "filename": "<string>"
    },
    {
      "id": "<string>" or <number>,
      "text": "<string>"
    }
  ]
}

-
rag_space_id is the RAG space ID.

-
model is the name of the model used to generate text embedding vectors in this RAG space.

-
entries is the number of elements in the values array.

-
values is an array of text document chunks and PDF filenames:

-
id is a document ID for a text document (shared by all chunks from that document), or for a PDF file.

Documents added to a RAG space before version 26.0.1 of the AI model server have numeric document IDs (for example, 1, 2, 3). Starting with version 26.0.1, document IDs are UUID strings (for example, "5f7677a0-3258-55a3-bc86-737005cb3574"). When working with RAG spaces that contain documents added before and after the ID format change, your scripts should handle both document ID formats.

See the Perform RAG Action script step.

-
filename is the name of a PDF file added to the space.

-
text is a chunk of a text document added to the space. Chunks from the same text document have the same id.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (437, 5, 'notes', 'Notes', '-
A RAG account must be configured using the Configure RAG Account script step before using this function.

-
This function is useful for verifying that a RAG space exists before performing operations on it. For a valid RAG account, if a space doesn''t exist or has no data in it, this function returns an error message:

[RAG Space] error. Reason: RAG space {space_id} not found

-
If the RAG account is invalid or doesn''t exist, this function returns "?".

-
The function can be used for auditing and monitoring of RAG spaces within your FileMaker solution.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (437, 6, 'ref-example1', 'Example 1', 'Gets information about all RAG spaces for a configured account named "customer-support-rag-account".

GetRAGSpaceInfo ( "customer-support-rag-account" ) can return the following if two RAG spaces contain data:

Copy

{
  "rag_space_list": [
    {
      "space_id": "knowledge-base",
      "model": "multi-qa-MiniLM-L6-cos-v1"
    },
    {
      "space_id": "meeting-notes",
      "model": "multi-qa-MiniLM-L6-cos-v1"
    }
  ]
}');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (437, 7, 'ref-examplen', 'Example 2', 'Gets information about a specific RAG space with ID "knowledge-base".

GetRAGSpaceInfo ( "customer-support-rag-account" ; "knowledge-base" ) can return the following JSON for a space with PDF files named "Terms.pdf" and "Policies.pdf" and a text document divided into three chunks (truncated for brevity). Notice that "Terms.pdf" has a numeric value for id because it was added to the RAG space using an earlier version of the AI model server (see Notes).

Copy

{
  "rag_space_id": "knowledge-base",
  "model": "multi-qa-MiniLM-L6-cos-v1",
  "entries": 5,
  "values": [
    {
      "id": 42,
      "filename": "Terms.pdf"
    },
    {
      "id": "f95d4266-66cd-5b50-a01b-07a4dd66c501",
      "filename": "Policies.pdf"
    },
    {
      "id": "5f7677a0-3258-55a3-bc86-737005cb3574",
      "text": "Customer support policies and procedures for handling returns and exchanges..."
    },
    {
      "id": "5f7677a0-3258-55a3-bc86-737005cb3574",
      "text": "Ensure that the item you''re returning is repackaged with all..."
    },
    {
      "id": "5f7677a0-3258-55a3-bc86-737005cb3574",
      "text": "You have 14 calendar days to return an item from the date you received it..."
    }
  ]
}');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (437, 8, 'ref-examplen', 'Example 3', 'Uses GetRAGSpaceInfo in a script to verify a RAG space exists before performing operations.

Copy

Configure RAG Account [ RAG Account Name: "customer-support-rag-account" ; Endpoint: "https://myserver.example.com/llm/v1/" ; API key: Global::RAG_API_Key ; Verify SSL Certificates ]

Set Variable [ $ragSpaceInfo ; Value: GetRAGSpaceInfo ( "customer-support-rag-account" ; "knowledge-base" ) ]

If [ PatternCount ( $ragSpaceInfo ; "[RAG Space] error" ) > 0 or PatternCount ( $ragSpaceInfo ; "?" ) > 0 ]

    # RAG space doesn''t exist. Handle error.

    Show Custom Dialog [ "Error" ; "The specified RAG space wasn''t found." ]

Else

    # RAG space exists. Proceed with operations.

    Set Variable [ $ragSpaceID ; Value: JSONGetElement ( $ragSpaceInfo ; "rag_space_id" ) ]

    Show Custom Dialog [ "Space Found" ; "RAG space ''" & $ragSpaceID & "'' is available to use." ]

End If');
