INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (438, 0, 'ref-format', 'Format', 'GetTableDDL ( tableOccurrenceNames ; ignoreError )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (438, 1, 'ref-param', 'Parameters', 'tableOccurrenceNames - a text expression for a JSON array of the table occurrences to return.

ignoreError - if set to True, returns DDL information for the table occurrences that cause no error. If False, returns DDL information when no table occurrences cause an error; otherwise returns "?" to indicate an error and logs the table occurrences that caused the error in the AI call log (see Set AI Call Logging script step).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (438, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (438, 3, 'ref-orig', 'Originated in version', '21.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (438, 4, 'ref-desc', 'Description', 'This function returns a DDL representation of the specified table occurrences. The DDL consists of SQL commands that can be used to define database schema (tables, fields, and relationships). You can provide the DDL returned by this function in a request to an AI model to create SQL queries that you can use to query your FileMaker Pro database. In fact, this is what the Perform SQL Query by Natural Language does using the same logic as this function to generate the DDL.

To improve the quality of the DDL returned by this function, follow the suggestions in Best practices for database schema in DDL and SQL query generation.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (438, 5, 'ref-example1', 'Example 1', 'GetTableDDL ( "[\"Meetings\", \"Topics\"]"; True) returns the following for a FileMaker Pro file containing table occurrences named Meetings and Topics:

Copy

CREATE TABLE "Meetings" (
"Title" varchar(255),
"Location" varchar(255),
"Date" datetime,
"Start Time" datetime,
"End Time" datetime,
"Duration" varchar(255),
"Note" varchar(255),
"PrimaryKey" varchar(255), /*Unique identifier of each record in this table*/
"CreatedBy" varchar(255), /*Account name of the user who created each record*/
"ModifiedBy" varchar(255), /*Account name of the user who last modified each record*/
"CreationTimestamp" datetime, /*Date and time each record was created*/
"ModificationTimestamp" datetime, /*Date and time each record was last modified*/
"Note_Embedding" varbinary(4096),
PRIMARY KEY (PrimaryKey)
);

CREATE TABLE "Topics" (
"ForeignKey" varchar(255), /*Unique identifier of each record in the related table*/
"PrimaryKey" varchar(255), /*Unique identifier of each record in this table*/
"ModifiedBy" varchar(255), /*Account name of the user who last modified each record*/
"ModificationTimestamp" datetime, /*Date and time each record was last modified*/
PRIMARY KEY (PrimaryKey),
FOREIGN KEY (ForeignKey) REFERENCES Meetings(PrimaryKey)
);

In the Meetings table, no field annotations have been set, so all fields are included. For fields with comments, text of the comments is included.

In the Topics table, field annotations have been set for four fields, so only those fields are included along with their annotations.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (438, 6, 'ref-examplen', 'Example 2', 'Turns on AI call logging, then for an array of table occurrence names, checks whether GetTableDDL returns an error with the ignoreError parameter set to False.

Copy

Set AI Call Logging [ On ; Filename: "ai-call.log" ; Verbose: Off ]
Set Variable [ $tableDDL ; Value:
    GetTableDDL ( JSONMakeArray ( "Meetings,Employees,Contact Info" ; "," ; JSONString ) ;
    False ) ]
If [ $tableDDL = "?" ]
    Show Custom Dialog [ "An error occurred. See ai-call.log in the Documents folder." ]
Else
    Show Custom Dialog [ $tableDDL ]
End If');
