INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (444, 0, 'ref-format', 'Format', 'ConvertToFileMakerPath ( standardPath ; format )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (444, 1, 'ref-param', 'Parameters', 'standardPath - any text expression or text field containing a path in a standard format.

format - a numeric value that specifies the standard format that standardPath is in (see below).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (444, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (444, 3, 'ref-orig', 'Originated in version', '19.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (444, 4, 'ref-desc', 'Description', 'This function performs the reverse operation of ConvertFromFileMakerPath. The format parameter can have the same values as in the ConvertFromFileMakerPath function.

When a standard path can''t be converted to a FileMaker path, this function returns "?".');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (444, 5, 'notes', 'Notes', '-
If standardPath is not in the format specified by the format parameter, this function may return an invalid FileMaker path or "?".

-
This function converts URL paths that use the fmp scheme to FileMaker paths with the fmnet prefix. All other returned FileMaker paths use the file prefix. See About path prefixes.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (444, 6, 'ref-example1', 'Example 1', 'ConvertToFileMakerPath ( "/Users/John Smith/Documents/test.xlsx" ; PosixPath ) returns:

-
file:/Macintosh HD/Users/John Smith/Documents/test.xlsx on a Mac where the root volume is named Macintosh HD.

-
file:/C:/Users/John Smith/Documents/test.xlsx on a Windows computer where the boot drive is C.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (444, 7, 'ref-examplen', 'Example 2', 'ConvertToFileMakerPath ( "C:\Users\John Smith\Documents\test.xlsx" ; WinPath ) returns file:/C:/Users/John Smith/Documents/test.xlsx.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (444, 8, 'ref-examplen', 'Example 3', 'Displays fmnet:/fmhost.example.com/My Clients.fmp12 after converting the URL in the $URL variable to a FileMaker path.

Copy

Set Variable [ $URL ; Value: "fmp://fmhost.example.com/My%20Clients.fmp12" ]
Show Custom Dialog [ ConvertToFileMakerPath ( $URL ; URLPath ) ]');
