INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (452, 4, 'ref-desc', 'Description', 'This function provides a way for a calculation to get the UUID of the layout object with which the calculation is associated without having to explicitly reference the object. With LayoutObjectUUID, you can create a single calculation formula that can be applied to different objects.

The LayoutObjectUUID function can be used only in the following types of layout object calculations:

-
the Web Address box in the Web Viewer Setup dialog box (see Working with web viewers on layouts)');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (452, 5, 'notes', 'Notes', '-
This function returns "?" when used in an unsupported layout object calculation.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (452, 6, 'ref-example1', 'Example 1', 'If ( LayoutObjectUUID = "393877C5-D0A2-43D0-88B5-08F9305852DA" ; 1 ; 0 ) returns 1 (true) in a web viewer''s Web Address box if the web viewer''s UUID is 393877C5-D0A2-43D0-88B5-08F9305852DA.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (452, 7, 'ref-examplen', 'Example 2', 'This example formula can be used in a web viewer''s Web Address box to pass the web viewer''s UUID to JavaScript running in the web viewer.

Copy

"data:text/html,
<!doctype html>
<html>
  <head>
    <script>
      var UUID = " & Quote ( LayoutObjectUUID ) & ";
      <!-- Script continues -->
    </script>
  </head>
  <body>
    <!-- Body of page -->
  </body>
</html>"');
