Returns an empty list if a user doesn''t have extended privileges assigned to the account used to open the file.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (454, 5, 'notes', 'Notes', '-
If you are logged in and running a script that is set to run with full access privileges, Get(AccountExtendedPrivileges) returns the extended privileges for your account''s privilege set, but Get(CurrentExtendedPrivileges) returns the extended privileges for the Full Access privilege set.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (454, 6, 'ref-example1', 'Example 1', 'If you are logged in with a privilege set that includes only the Access via FileMaker WebDirect extended privilege:

Get ( AccountExtendedPrivileges ) returns fmwebdirect.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (454, 7, 'ref-examplen', 'Example 2', 'Assume the [Read-Only Access] privilege set includes the Access via FileMaker Network extended privilege, and the [Full Access] privilege set includes the Access via FileMaker Network and Access via FileMaker WebDirect extended privileges. If you are logged in with the Guest account and run a script set to run with full access privileges:

Get ( AccountExtendedPrivileges ) returns fmapp

Get ( CurrentExtendedPrivileges ) returns

fmapp
fmwebdirect');
