INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (455, 4, 'ref-desc', 'Description', 'If the current user''s account type is one of the following, this function returns information about the group the user is in; otherwise, it returns an empty string.
For account type
Returns
Claris ID or external identity provider (IdP) account
Claris ID group or external IdP group name
