INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (455, 6, 'ref-examplen', 'Example 2', 'Returns Marketing if you are signed in to an external server account that belongs to the Marketing group on the authentication server.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (455, 7, 'ref-examplen', 'Example 3', 'Returns e849544f-8a50-4c6e-b1c3-d38c7dc2bfd3 if you are signed in to an account that belongs to a group with the ID "e849544f-8a50-4c6e-b1c3-d38c7dc2bfd3" on Microsoft Entra ID, an OAuth identity provider.');
