INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (456, 0, 'ref-format', 'Format', 'Get ( AccountName )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (456, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (456, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (456, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (456, 4, 'ref-desc', 'Description', 'If a user authenticates with the default Admin account, Get(AccountName) returns Admin. If the FileMaker Pro Guest account is used, then [Guest] will be returned.

When an account authenticates via an external server, the Claris ID identity provider system, an external identity provider (IdP), or an OAuth identity provider with group credentials, Get(AccountName) returns the name of the authenticated account being used by the current user of the file, not the group the user is in. (The group name appears in the Manage Security dialog box when you define account access and privileges in FileMaker Pro.)');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (456, 5, 'notes', 'Notes', '-
Calculations should not depend on whether the account name returned by Get(AccountName) uses uppercase or lowercase letters. You can use a function such as Lower to change the returned text to a known case.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (456, 6, 'ref-example1', 'Example 1', 'Returns bob@example.com when bob@example.com is the Claris ID user name that was used to sign in to the database file.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (456, 7, 'ref-examplen', 'Example 2', 'If a user enters BOB when signing in to the Bob account (a FileMaker file account), Get(AccountName) returns BOB.');
