INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (457, 4, 'ref-desc', 'Description', 'Returns:

-
The number of days before the password must be changed.

-
0 if the password is expired.

-
-1 if the account doesn''t have a password, the password has no expiration restrictions, or is not a FileMaker file account (see Editing FileMaker file accounts).

Password expiration is set by the Must be changed every <n> days privilege in the account''s privilege set. See Editing other privileges.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (457, 5, 'ref-example1', 'Example 1', 'Returns 5 if the user''s account expires in 5 days.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (457, 6, 'ref-examplen', 'Example 2', 'Returns 0 if the user''s password is already expired.');
