INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (458, 6, 'ref-examplen', 'Example 2', 'For a user in the sales department, Get(AccountPrivilegeSetName) might return [Data Entry Only].');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (458, 7, 'ref-examplen', 'Example 3', 'For a user with Read-Only Access to a database who is running a script that is set to run with full access privileges, Get(AccountPrivilegeSetName) returns [Read-Only Access] but Get(CurrentPrivilegeSetName) returns [Full Access] (for the current script).');
