INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (460, 4, 'ref-desc', 'Description', 'When the focus is in a repeating field, this function returns the contents of the active repetition. The result type of the active field depends upon the data type of the active field and the result type assigned to the Get(ActiveFieldContents) calculation function.

This type of calculation is most useful if used in a script when you want to examine data in different fields as the script proceeds.');
