INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (462, 4, 'ref-desc', 'Description', 'Returns the table occurrence name for the active field. If there is no active field, this function returns an empty string.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (462, 5, 'ref-example1', 'Example 1', 'There are two fields, Teachers::Name and Coaches::Name, on the current layout based on the Classes table occurrence. The Classes table occurrence is related to the Teachers table occurrence and the CoachesA table occurrence (whose source table is Coaches). Creating a script that returns the result of Get(ActiveFieldTableName) to a third field will return Teachers when the script is performed after clicking in the Teachers::Name field, or will return CoachesA after clicking in the Coaches::Name field.');
