INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (463, 5, 'notes', 'Notes', '- Clicking a button, a popover button, or a panel control does not give it the focus. To give one of these objects the focus, you must press Tab or perform the Go to Object script step to navigate to a button, tab panel, or slide panel.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (463, 6, 'ref-example1', 'Example 1', 'There is a named field on the current layout called customerName. When the focus is on the field, Get(ActiveLayoutObjectName) returns customerName.');
