INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (464, 0, 'ref-format', 'Format', 'Get ( ActiveModifierKeys )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (464, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (464, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (464, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (464, 4, 'ref-desc', 'Description', 'The number returned is calculated by summing numbers representing each modifier key (for example, Control+Shift) being pressed. The values assigned to the keys are:

- Shift = 1

- Caps Lock = 2

- Ctrl (Windows) and Control (macOS) = 4

- Alt (Windows) and Option (macOS) = 8

- Command (macOS) = 16

You could use this function in a script that includes a custom dialog box script step (with an OK and Cancel button) to perform some special action if the user presses the Alt (or Option) key while clicking OK.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (464, 5, 'notes', 'Notes', '- In FileMaker WebDirect and FileMaker Go, this function is not supported and returns 0.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (464, 6, 'ref-example1', 'Example 1', 'Returns 9 when Shift+Alt is pressed on a computer running Windows.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (464, 7, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (465, 0, 'ref-format', 'Format', 'Get ( ActivePortalRowNumber )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (465, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (465, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (465, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (465, 4, 'ref-desc', 'Description', 'When no portal row contains the focus, this function returns 0. If there are multiple windows open in the current file, each window can have its own portal row number value, but results are returned for only the foreground window. If a user navigates to a portal without selecting a specific portal row and without making an object active within a specific portal row, Get(ActivePortalRowNumber) returns row 0 rather than row 1.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (465, 5, 'notes', 'Notes', '- If a field on a layout is defined as Get(ActivePortalRowNumber), the window must be refreshed before the field will display the current portal row number.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (465, 6, 'ref-example1', 'Example 1', 'Returns 5 when the fifth row of a portal has the focus, or when the focus is in a field in the fifth portal row.

Returns 1 after the Go to Portal Row [Select: Off ; First] script step runs.

Returns 0 when a portal is not selected.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (465, 7, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas

- Using operators in formulas

- Get(TriggerModifierKeys) function');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (466, 0, 'ref-format', 'Format', 'Get ( ActiveRecordNumber )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (466, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (466, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (466, 3, 'ref-orig', 'Originated in version', '17.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (466, 4, 'ref-desc', 'Description', 'The value returned is the current record number displayed in the navigation controls in the status toolbar. It is determined by the relative place of the record in the found set, and it changes depending on the find criteria and the sort order.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (466, 5, 'notes', 'Notes', '- To return a value that uniquely and permanently identifies a record in this table, use the Get(RecordID) function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (466, 6, 'ref-example1', 'Example 1', 'Returns 4 when the fourth record in the found set has focus.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (466, 7, 'ref-examplen', 'Example 2', 'In a portal that shows records from the current table, suppose you want to display a button in a portal row only when the row is the active portal row. (This condition occurs when the record''s position in the current found set is the same as the number of the record that has focus.)

To hide the button when the row is not the active portal row, select the button. In the Data  tab of the Inspector, enter the following formula for Hide object when:

Copy

not ( Get ( RecordNumber ) = Get ( ActiveRecordNumber ) )

You can also apply this example to show a button only in the active record in List View.

See Creating portals for list-detail layouts and Hiding or showing layout objects.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (466, 8, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas

- Get(RecordNumber) function');
