INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (472, 4, 'ref-desc', 'Description', 'Returns:

-
x86_64 for the 64-bit version of FileMaker Pro (Windows, macOS on Intel processors), FileMaker Server, FileMaker Cloud, FileMaker WebDirect, the FileMaker Data API, and Custom Web Publishing

-
arm64 for FileMaker Go running on a 64-bit ARM-based device, for FileMaker Pro running on a Mac with Apple silicon, for FileMaker Server running on a Mac with Apple silicon, or for FileMaker Server running on a 64-bit ARM-based Linux computer');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (472, 5, 'ref-example1', 'Example 1', 'Returns Apple silicon if evaluated on a Mac with Apple silicon.

Copy

If (
    Get ( SystemPlatform ) = 1 and Get ( ApplicationArchitecture ) = "arm64" ;
    "Apple silicon"
)');
