INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (478, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (478, 3, 'ref-orig', 'Originated in version', '13.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (478, 4, 'ref-desc', 'Description', 'Get(ConnectionAttributes) returns an empty string if:

- the current file is not hosted

- the host is not FileMaker Server or FileMaker Cloud

- the host does not use an SSL certificate to secure the connection to the client

- the host is a single-machine deployment of FileMaker Server on macOS');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (478, 5, 'ref-example1', 'Example 1', 'If the host is named "group_server" and the current SSL certificate was issued by XYZ Inc., Get(ConnectionAttributes) returns:

[ Peer Certificate ]
commonName: group_server
CA Issuers: XYZ Inc.');
