INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (479, 0, 'ref-format', 'Format', 'Get ( ConnectionState )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (479, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (479, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (479, 3, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (479, 4, 'ref-desc', 'Description', 'Secure connections are encrypted using SSL. If security is important in your environment, your server administrator needs to install a custom SSL certificate.

Returns:

- 0 for no network connection for the current file.

- 1 for a connection that is not encrypted (to FileMaker Server with SSL disabled, or to a FileMaker Pro host).

- 2 for a connection that is encrypted but for which the SSL certificate cannot be verified. You may be connected to a server pretending to be your actual destination, which could put your confidential information at risk.

- 3 for a connection that is encrypted with a verified SSL certificate.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (479, 5, 'notes', 'Notes', '- Get(ConnectionState) is intended for FileMaker Pro or FileMaker Go client connections. If a script is run via FileMaker WebDirect, the FileMaker Data API, Custom Web Publishing, or a server-side script, there may be no network connection to verify. In this case, this function returns only 1 or 2.

- For FileMaker WebDirect, this function does not reflect the state of the connection between the web browser and FileMaker Server or FileMaker Cloud. Instead, the web browser verifies and displays the state of its connection.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (479, 6, 'ref-example1', 'Example 1', 'Returns 3 when the connection is encrypted with a verified SSL certificate.');
