- Opening shared files as a client');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (480, 0, 'ref-format', 'Format', 'Get ( CurrentDate )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (480, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (480, 2, 'ref-return', 'Data type returned', 'date');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (480, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (480, 4, 'ref-desc', 'Description', 'The format of the result of this function varies based on the date format that was in use when the database file was created. In the United States, dates are generally in the format MM/DD/YYYY. You can change the date and time formats in your operating system.

If the result is displayed in a field, it is formatted according to the date format of the field in the current layout.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (480, 5, 'ref-example1', 'Example 1', 'Returns 2/2/2019 when the system date is set to February 2, 2019.

Get ( CurrentDate ) - Date ( 1 ; 5 ; 2019 ) returns 4 when the system date is set to January 9, 2019.

For an example script, see Exit Application script step.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (480, 6, 'related', 'Related topics', '- Functions reference

