INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (481, 4, 'ref-desc', 'Description', 'The keywords in the list are separated by carriage returns. Extended privileges are additional access rights assigned to the privilege set of an account access. See About accounts, privilege sets, and extended privileges.

Returns an empty list if a user doesn''t have extended privileges assigned for the current database file.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (481, 5, 'notes', 'Notes', '-
If you are logged in and running a script that is set to run with full access privileges, Get(AccountExtendedPrivileges) returns the extended privileges for your account''s privilege set, but Get(CurrentExtendedPrivileges) returns the extended privileges for the Full Access privilege set.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (481, 6, 'ref-example1', 'Example 1', 'The account that is evaluating this calculation uses a privilege set that includes the extended privilege of Access via FileMaker WebDirect (keyword "fmwebdirect"):

Position(Get(CurrentExtendedPrivileges); "fmwebdirect"; 1; 1) returns a value greater than 0.');
