INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (486, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (486, 2, 'ref-return', 'Data type returned', 'number, time');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (486, 3, 'ref-orig', 'Originated in version', '19.6');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (486, 4, 'ref-desc', 'Description', 'Returns the current time without time zone adjustments in the form of the number of microseconds since 1/1/0001. UTC time zone adjustments must be applied to return your local time.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (486, 5, 'notes', 'Notes', '- In client-server and peer-to-peer environments, this function evaluates the status of the client machine running the script (not the host machine).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (486, 6, 'ref-example1', 'Example 1', 'Calculates the amount of time it takes to find and sort records as specified in the script.

Copy

Set Variable [$START ; Get ( CurrentTimeUTCMicroseconds )]
Go to Layout ["Invoices"]
Perform Find [Restore]
Sort Records [Restore; With dialog: Off]
Set Variable [$END ; Get ( CurrentTimeUTCMicroseconds )]
Show Custom Dialog ["Script Duration" ; ( $END - $START ) & " microseconds"]');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (486, 7, 'ref-examplen', 'Example 2', 'Calculates the local time for the specified time zone. When the time in UTC is 08:43:55.304 and TimeAdjustment contains -7:

GetAsTime ( GetAsTimestamp ( Get ( CurrentTimeUTCMicroseconds ) / 1000000 ) + ( Location::TimeAdjustment * 3600 ) ) returns 1:43:55.304 PM.');
