INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (496, 4, 'notes', 'Notes', '- This function is supported only in FileMaker Pro and FileMaker Go. In other FileMaker products, it''s not supported and returns an empty string.

- The returned path is in FileMaker format but doesn''t include a path prefix. See About path prefixes.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (496, 5, 'ref-example1', 'Example 1', 'Returns /C:/Program Files/FileMaker/FileMaker Pro/ in Windows.

Returns /Macintosh HD/Applications/ in macOS.

Each part of the path may vary from these examples, so don''t rely on the path to follow a particular pattern.');
