INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (498, 0, 'ref-format', 'Format', 'Get ( FilePath )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (498, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (498, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (498, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (498, 4, 'ref-desc', 'Description', 'In Windows, the full path is file:/drive:/folder/filename for local files. For remote files, the full path is file://volume/folder/filename.

In macOS, the full path is file:/volume/folder/filename for local and remote files.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (498, 5, 'ref-example1', 'Example 1', 'Returns file:/C:/Users/Username/Documents/Clients.fmp12 for a local file in Windows.

Returns file:/Sharename/Documents/Clients.fmp12 for remote files in Windows.

Returns file:/Macintosh HD/Users/Username/Documents/Clients.fmp12 for a local file in macOS.

Returns fmnet:/192.168.10.10/Clients.fmp12 for a FileMaker Pro networked file.

Each part of the path may vary from these examples, so don''t rely on the path to follow a particular pattern.');
