INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (501, 0, 'ref-format', 'Format', 'Get ( GuidedAccessState )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (501, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (501, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (501, 3, 'ref-orig', 'Originated in version', '26.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (501, 4, 'ref-desc', 'Description', 'Guided Access keeps an iOS or iPadOS device in a single app. You can set up FileMaker Go as the single app that has your file open—for example, to run as a kiosk. Use this function to conditionally show or hide administrative controls based on whether Guided Access is enabled, or to display reminders to enable Guided Access during kiosk setup.

This function returns:

-
0 if Guided Access is turned off.

-
1 if Guided Access is turned on.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (501, 5, 'notes', 'Notes', '-
On platforms other than iOS and iPadOS, this function is not supported and returns an empty string.');
