INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (503, 4, 'ref-desc', 'Description', 'Returns a value when the current file is hosted. Otherwise, it returns an empty string. If hosted by FileMaker Pro, this function returns a value on clients but returns an empty string on the host.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (503, 5, 'ref-example1', 'Example 1', 'Returns Pro 26.0.1 on clients when the host computer is running FileMaker Pro version 26.0.1.

Returns Server 26.0.1 when the host computer is running FileMaker Server version 26.0.1.

Returns Cloud Server 2.26.0.57 when the host computer is running FileMaker Cloud version 2.26.0 build 57.');
