INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (504, 0, 'ref-format', 'Format', 'Get ( HostIPAddress )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (504, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (504, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (504, 3, 'ref-orig', 'Originated in version', '8.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (504, 4, 'ref-desc', 'Description', 'If the current file isn''t being hosted, an empty string is returned.

If IPv4 and IPv6 addresses are available for remotely hosted files, the address is returned in the most common or default format. This might not be the same format that was used when connecting to the host.

If the current calculation is stored and you specify its context, this function will be evaluated based on that context; otherwise, it will be evaluated based on the context of the current window.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (504, 5, 'notes', 'Notes', '- In FileMaker WebDirect, Get(HostIPAddress) returns the physical IP address of the host machine.

- If the host machine has both IPv4 and IPv6 addresses, Get(HostIPAddress) returns only the IP address that the client used to connect to the host.

- This function is not supported in FileMaker Cloud.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (504, 6, 'ref-example1', 'Example 1', 'Returns one of the following when the current file is being hosted:

- IPv4: 14.156.13.121

- IPv6: [2001:0DB8:85A3:08D3:1319:8A2E:0370:7334]');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (504, 7, 'ref-examplen', 'Example 2', 'Returns one of the following when accessing a locally hosted file:

- 127.0.0.1 if connected to 127.0.0.1

- [::1] if connected to localhost

- 14.156.13.121 if connected to the computer''s IP address or evaluated in FileMaker WebDirect.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (504, 8, 'related', 'Related topics', '- Functions reference

