INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (506, 0, 'ref-format', 'Format', 'Get ( InstalledFMPlugins )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (506, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (506, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (506, 3, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (506, 4, 'ref-desc', 'Description', 'This function is useful for determining whether an installed plug-in is newer or older than a plug-in required by a file. The version number is returned if it is available.

If multiple plug-ins are installed, Get(InstalledFMPlugins) returns values for each plug-in on separate lines, separated by carriage returns.

Get(InstalledFMPlugins) returns plug-in version information only when plug-in developers have entered version information in the resource file (Windows) or the info.plist file (macOS).

macOS: Plug-ins are stored as packages.

The enabled state is returned as follows:

- Enabled – The plug-in is enabled in the FileMaker Pro settings and can be loaded.

- Disabled – The plug-in is disabled in the FileMaker Pro settings and cannot be loaded.

- Ignored – The plug-in failed to load, which could be due to software incompatibility.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (506, 5, 'ref-example1', 'Example 1', 'When:

- MyPlugin1 is installed and is enabled in the Plug-ins tab in the Settings dialog.

- MyPlugin2 is installed and is disabled in the Plug-ins tab in the Settings dialog.

- MyPlugin3 could not be loaded.

Get(InstalledFMPlugins) returns:

MyPlugin1;1.0;Enabled

MyPlugin2;1.1;Disabled

MyPlugin3; ;Ignored');
