INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (517, 5, 'ref-example1', 'Example 1', 'There are two layouts, Teachers Layout and Coaches Layout, with corresponding table occurrences named Teachers and Coaches. An unstored calculation of Get(LayoutTableName) returns Teachers when the current layout is Teachers Layout and returns Coaches when the current layout is Coaches Layout.');
