After a record is deleted, this function returns an empty string.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (520, 5, 'ref-example1', 'Example 1', 'When the Invoices::Customer Name and Invoices::Company fields are modified and the record is open, Get(ModifiedFields) returns:

Customer Name
Company');
