INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (521, 4, 'ref-desc', 'Description', 'Returns:

- 0 when network sharing is off

- 1 when network sharing is on, you''re accessing the database file from the host computer, and either all users or a specific group of users (based on their privilege set) have network access to the database file

- 2 when network sharing is on, you''re accessing the database file from a client computer, and either all users or a specific group of users (based on their privilege set) have network access to the database file');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (521, 5, 'notes', 'Notes', '- If the current calculation is stored and you specify its context, this function will be evaluated based on that context; otherwise, it will be evaluated based on the context of the current window.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (521, 6, 'ref-example1', 'Example 1', 'Returns 0 when access is denied to other users.

For an example script, see Set Multi-User script step.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (521, 7, 'related', 'Related topics', '- Sharing files on a network

