INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (524, 0, 'ref-format', 'Format', 'Get ( OpenDataFileInfo )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (524, 1, 'ref-param', 'Parameters', 'None');
