INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (524, 4, 'ref-desc', 'Description', 'Information about each open data file is separated by a line break. Each line follows this format:

Copy

<file ID><tab><path><line break>

File IDs are returned by the Open Data File script step when a file is opened. Paths are named according to FileMaker Pro conventions (see Creating file paths).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (524, 5, 'ref-example1', 'Example 1', 'When two data files are open, this function may return the following:

Windows:

Copy

1        file:/C:/Users/user_name/Documents/change.log
2        file:/C:/Users/user_name/Desktop/sap001.txt

macOS:

Copy

15        file:/Macintosh HD/Users/user_name/Documents/change.log
16        file:/Macintosh HD/Users/user_name/Desktop/sap001.txt');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (524, 6, 'ref-examplen', 'Example 2', 'Returns the number of open data files.

Copy

ValueCount ( Get ( OpenDataFileInfo ) )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (524, 7, 'ref-examplen', 'Example 3', 'Returns the number of open data files that are in the Documents folder.

Copy

PatternCount ( Get( OpenDataFileInfo ) ; Get ( DocumentsPath ) )');
