INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (527, 0, 'ref-format', 'Format', 'Get ( PersistentID )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (527, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (527, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (527, 3, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (527, 4, 'ref-desc', 'Description', 'Returns a unique, unchanging, 32-digit hexadecimal string identifier for the computer or device on which FileMaker Pro, FileMaker Go, FileMaker Server, FileMaker Cloud, or the current FileMaker WebDirect session is running. Get(PersistentID) helps you identify devices that access your custom app.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (527, 5, 'notes', 'Notes', '-
If web browser cookies are cleared during a FileMaker WebDirect session, the value returned by Get(PersistentID) changes.

-
If a FileMaker Go user restores an iOS or iPadOS backup to a different device, the value returned by Get(PersistentID) changes. If a backup is restored to the same device, the returned value remains the same. For more information, see the Knowledge Base.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (527, 6, 'ref-example1', 'Example 1', 'For a FileMaker Pro client or a FileMaker Go client, Get(PersistentID) returns a value such as 78569d0bd40b898a64e7d08ccdea8220.');
