-
Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (528, 0, 'ref-format', 'Format', 'Get ( PreferencesPath )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (528, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (528, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (528, 3, 'ref-orig', 'Originated in version', '8.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (528, 4, 'ref-desc', 'Description', 'In Windows, the path format is /Drive:/Users/UserName/AppData/Local/.

In macOS, the path format is /DriveName/Users/UserName/Library/Preferences/.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (528, 5, 'notes', 'Notes', '- This function is supported only in FileMaker Pro and FileMaker Go. In other FileMaker products, it''s not supported and returns an empty string.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (528, 6, 'ref-example1', 'Example 1', 'Returns /C:/Users/John Smith/AppData/Local/ for a user named John Smith in Windows.

Returns /Macintosh HD/Users/John Smith/Library/Preferences/ for a user named John Smith in macOS.

Each part of the path may vary from these examples, so don''t rely on the path to follow a particular pattern.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (528, 7, 'related', 'Related topics', '- Functions reference

