INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (536, 4, 'ref-desc', 'Description', 'This function returns the state of the current record pertaining to the current user. It returns:

- 0 for a closed (committed) record

- 1 for a new record that hasn''t been committed

- 2 for a modified record that hasn''t been committed

- 3 for a deleted record that hasn''t been committed');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (536, 5, 'ref-example1', 'Example 1', 'Returns 1 if the current record is a new record that the current user hasn''t saved.

For an example script, see Revert Record/Request script step.');
