INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (541, 5, 'notes', 'Notes', '- In FileMaker WebDirect, this function is not supported and returns 32.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (541, 6, 'ref-example1', 'Example 1', 'Returns 32 on a display showing millions (232) of colors.

Returns 16 on a display showing thousands (216) of colors.

Returns 4 on a VGA display.

Returns 1 on a black-and-white display.');
