INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (543, 0, 'ref-format', 'Format', 'Get ( ScreenScaleFactor )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (543, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (543, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (543, 3, 'ref-orig', 'Originated in version', '13.0.2');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (543, 4, 'ref-desc', 'Description', 'In macOS and FileMaker Go, this function returns a scale factor based on the relative pixel density of the screen; for example:

-
1 for a standard-resolution device without a Retina display (one pixel per point)

-
2 for a high-resolution device with a Retina display (four pixels per point)

-
3 for a higher-resolution device with a Retina display (nine pixels per point)

In Windows, this function returns the scale factor specified in Settings.

In FileMaker WebDirect, server-side scripts, the FileMaker Data API, and Custom Web Publishing, this function returns 1.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (543, 5, 'ref-example1', 'Example 1', 'Get(ScreenScaleFactor) returns 2 on iPad with Retina display.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (543, 6, 'ref-examplen', 'Example 2', 'Detects the screen scale factor, then goes to a layout designed for a large scale factor or goes to a standard layout.

Copy

If [Get ( ScreenScaleFactor ) = 1.5]
    Go to Layout [Invoices Factor 150%]
Else
    Go to Layout [Invoices]
End If');
