INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (548, 0, 'ref-format', 'Format', 'Get ( ScriptResult )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (548, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (548, 2, 'ref-return', 'Data type returned', 'text, number, date, time, timestamp, container');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (548, 3, 'ref-orig', 'Originated in version', '8.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (548, 4, 'ref-desc', 'Description', 'Use this function as part of a calculation evaluated within a script. If a sub-script doesn''t return a result, then the contents of the script result will either be empty or the value of any previous sub-script result. To control the value of a sub-script result, use the Exit Script script step in the sub-script and specify a result.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (548, 5, 'ref-example1', 'Example 1', 'In the following example, the Find Customers script returns the results of a find request when it is called from the Do Reports script. Script Find Customers uses the optional script result of the Exit Script script step. Script Do Reports then uses Get(ScriptResult) to determine what other script steps should be performed based on the returned result stored in Get(ScriptResult).

Find Customers

Copy

Set Error Capture [On]
Perform Find [Restore]
New Record/Request
Exit Script [Text Result: Get(FoundCount) < 10]

Do Reports

Copy

Perform Script [ Specified: From list ; "Find Customers" ;
Parameter: ]
If [Get(ScriptResult) = 0]
        Show Custom Dialog ["You have created 10 records already."]
End If');
