INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (550, 4, 'ref-desc', 'Description', 'Returns:

- 0 if the records in the active table are not sorted

- 1 if the records in the active table are sorted

- 2 if the records in the active table are partially sorted (semi-sorted)

Each window has its own sort state.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (550, 5, 'notes', 'Notes', '- When records are imported from another file to a previously found and sorted set, the records in a sorted set may exist in a semi-sorted state. To include the imported records in the sort order, sort the found set after importing.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (550, 6, 'ref-example1', 'Example 1', 'Returns 1 when the records in the active table are sorted.');
