INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (552, 4, 'ref-desc', 'Description', 'In Windows, this function returns the current high contrast default color scheme name if the high contrast option is enabled in Windows Settings under Ease of Access and if the high contrast color scheme is active. Returns an empty string if the option is unavailable or inactive.

In macOS, iOS, and iPadOS, this function returns the current system appearance name. You can use this to detect when the system is using the dark appearance (Dark Mode).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (552, 5, 'notes', 'Notes', '- This function is not supported and returns an empty string:

- in FileMaker WebDirect

- when evaluated by a Linux host');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (552, 6, 'ref-example1', 'Example 1', 'Returns High Contrast White when the Windows theme is set to High Contrast White.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (552, 7, 'ref-examplen', 'Example 2', 'Returns DarkAqua when macOS uses the dark system appearance; returns Aqua when it uses the light appearance.');
