INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (554, 0, 'ref-format', 'Format', 'Get ( SystemIPAddress )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (554, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (554, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (554, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (554, 4, 'ref-desc', 'Description', 'IP addresses are separated by carriage returns.

In FileMaker WebDirect, Get(SystemIPAddress) returns the IP address of the interface used to connect to the host.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (554, 5, 'ref-example1', 'Example 1', 'Suppose a machine has the following active physical interfaces:

- an Ethernet card not connected to a network with an IP address of 10.10.10.10

- a Wi-Fi interface with an IP address of 192.168.1.1

- a VPN connection with an IP address of 172.172.172.172

The function returns:

192.168.1.1
172.172.172.172');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (554, 6, 'ref-examplen', 'Example 2', 'Suppose a machine has the following active physical interfaces:

- an Ethernet card not connected to a network with an IP address of 2001::10

- a Wi-Fi interface with an IP address of 3FFE:FFFF:101::230:6EFF:FE04:D9FF/48

- a VPN connection with an IP address of 2001:0DB8:85A3:08D3:1319:8A2E:0370:7334

The function returns:

3FFE:FFFF:101::230:6EFF:FE04:D9FF/48
2001:0DB8:85A3:08D3:1319:8A2E:0370:7334');
