INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (557, 5, 'notes', 'Notes', '- In FileMaker WebDirect, this function is not supported and returns an empty string.

- In FileMaker Go, this function is not a reliable method for obtaining the address on an iOS or iPadOS device. To identify a device, use the Get(PersistentID) function instead. For more information, see the Knowledge Base.');
