INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (560, 4, 'ref-desc', 'Description', 'Returns:

-
6.3 for Windows 8.1

-
10.0 for Windows 10

-
11.0 for Windows 11

-
26.0 for macOS, iOS, or iPadOS version 26.0

-
<operating system or device> <web browser> <browser version> for FileMaker WebDirect

FileMaker WebDirect: For <operating system or device>, returns:

-
Win for a Windows operating system

-
Mac for a macOS operating system

-
Linux for a Linux operating system

-
iPad for iPad

-
iPhone for iPhone

-
Android for an Android device

-
Other for an unknown operating system or device

FileMaker WebDirect: For <web browser>, returns:

-
Safari for the Safari browser

-
Edge for the Edge browser

-
IE for the Internet Explorer browser

-
Chrome for the Chrome browser

-
Other for an unknown browser

For browser version, returns the version of the web browser accessing FileMaker WebDirect.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (560, 5, 'ref-example1', 'Example 1', 'Returns 26.0 when the current operating system is macOS version 26.0.

Returns iPad Safari 26.0 for iPad using FileMaker WebDirect in Safari version 26.0.

Returns Win Chrome 148.0 for a Windows computer using FileMaker WebDirect in Chrome version 148.0.');
