INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (561, 0, 'ref-format', 'Format', 'Get ( TemporaryPath )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (561, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (561, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (561, 3, 'ref-orig', 'Originated in version', '9.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (561, 4, 'ref-desc', 'Description', 'The temporary folder name begins with S, followed by a number representing the session of the database engine during which the operation took place. Because your operating system controls the location of temporary files, the exact path returned may be different from the examples shown. The actual path returned also depends on which FileMaker client is executing the function.

In FileMaker Pro, the temporary folder and any files placed in it are deleted when FileMaker Pro is exited or quit. In server-side scripts, each script runs in its own session; once the script is completed, the session terminates and the temporary folder is deleted.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (561, 5, 'notes', 'Notes', '- In FileMaker WebDirect, the FileMaker Data API, and Custom Web Publishing, this function is not supported and returns an empty string.

- The returned path is in FileMaker format but doesn''t include a path prefix. See About path prefixes.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (561, 6, 'ref-example1', 'Example 1', 'Returns:

- Windows: /C:/Users/username/AppData/Local/Temp/S10/

- macOS: /Macintosh HD/var/folders/r8/k3_nw76d6t95mh6cf3d21fpc0000gn/T/S10/

Each part of the path may vary from these examples, so don''t rely on the path to follow a particular pattern.

For an example script, see Perform Script On Server script step.');
