INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (564, 5, 'notes', 'Notes', '- In FileMaker Go, the value returned by this function does not indicate the state of the touch keyboard if the active field is a concealed edit box, because FileMaker Go always displays the touch keyboard for a concealed edit box.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (564, 6, 'ref-example1', 'Example 1', 'Checks the current setting of the touch keyboard and disables the touch keyboard if it is enabled.

