INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (573, 0, 'ref-format', 'Format', 'Get ( UserName )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (573, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (573, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (573, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (573, 4, 'ref-desc', 'Description', 'For each type of FileMaker client, this function returns the following:
For client  | Returns
FileMaker Pro  | the user name specified by the user in Settings (see Changing general settings)
FileMaker Go  | the user name specified by the user in the Settings menu
FileMaker WebDirect  | the value [WebDirect-<xxxxx>], where <xxxxx> is the last five digits of the current persistent ID (see the Get(PersistentID) function)
FileMaker Script Engine (server-side scripts)  |

-
the schedule name, if the script is run by a schedule

-
<script name> - <account name> <x>, where <x> is the number of scripts run since the FileMaker Script Engine was started
FileMaker Data API,
Custom Web Publishing,
ODBC/JDBC,
OData  | the account name used to authenticate

Important For greater security, use the Get(AccountName) function to track and manage user access: a user cannot change the account name used to log in to a database file.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (573, 5, 'ref-example1', 'Example 1', 'Returns Sharon Lloyd when Sharon Lloyd is the current user. For an example script, see Add Account script step.');
