INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (575, 0, 'ref-format', 'Format', 'Get ( UUID )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (575, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (575, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (575, 3, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (575, 4, 'ref-desc', 'Description', 'Returns a unique 16-byte (128-bit) string. For example, you can use this function to generate a unique ID of a record.

For unstored calculations, returns a new string each time Get(UUID) is evaluated.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (575, 5, 'ref-example1', 'Example 1', 'Auto-enter calculation: In a text field, specify the auto-enter calculation Get(UUID). See Defining automatic data entry.

Every new record has a unique ID in the field—for example:

E47E7AE0-5CF0-FF45-B3AD-C12B3E765CD5

You can use this technique to define a primary key field, if you can''t use the Get(UUIDNumber) function because it requires a later version of FileMaker Pro.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (575, 6, 'ref-examplen', 'Example 2', 'Unstored calculation: In a calculation field, specify the calculation Get(UUID). For Storage Options, select Do not store calculation results. Every time a record is accessed, a new string is generated.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (575, 7, 'related', 'Related topics', '- Functions reference

- Get(UUIDNumber) function

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (576, 0, 'ref-format', 'Format', 'Get ( UUIDNumber )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (576, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (576, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (576, 3, 'ref-orig', 'Originated in version', '17.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (576, 4, 'ref-desc', 'Description', 'Returns a unique, 24-byte (192-bit) number. For example, you can use this function to generate a unique ID of a record. Using this function instead of Get(UUID) as the calculated value of a primary key field may improve the performance of operations based on relationships.

For unstored calculations, returns a new number each time Get(UUIDNumber) is evaluated.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (576, 5, 'ref-example1', 'Example 1', 'Auto-enter calculation: In a number field, specify the auto-enter calculation Get(UUIDNumber). See Defining automatic data entry.

Every new record has a unique ID in the field—for example:

3351455178917488228606469712264530601969081773070792730006

or 3.3515E+57, if displayed in a field with data formatting set to General.

You can use this technique to define a primary key field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (576, 6, 'ref-examplen', 'Example 2', 'Unstored calculation: In a calculation field, specify the calculation Get(UUIDNumber). For Storage Options, select Do not store calculation results. Every time a record is accessed, a new number is generated.');
