INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (577, 0, 'ref-format', 'Format', 'Get ( WindowContentHeight )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (577, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (577, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (577, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (577, 4, 'ref-desc', 'Description', 'The content area depends on the current size of the active window but doesn''t include the title bar, scroll bars, and page margins. The content area is the space inside these controls. It does not include the status toolbar if it is currently showing.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (577, 5, 'notes', 'Notes', '- In FileMaker WebDirect, the content area includes the scroll bars and footer area.

- In FileMaker Go, the content area includes the layout but doesn''t include the status bar, menu bar, or toolbar.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (577, 6, 'ref-example1', 'Example 1', 'In macOS, returns 400 when the current window height is 437 and the status toolbar isn''t showing.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (577, 7, 'ref-examplen', 'Example 2', 'In macOS, the example below combines Get(WindowContentHeight) with Get(WindowHeight) to determine the height of the title bar and horizontal scroll bar:

Get(WindowHeight) - Get(WindowContentHeight) returns 37 when the window height is 437 and the status toolbar isn''t showing.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (577, 8, 'ref-examplen', 'Example 3', 'For iPhone 5.8-inch displays in portrait orientation, the height is 44 points for the menu bar, 27 points for the toolbar, and 44 points for the status bar. The Get(WindowContentHeight) function returns:

663 when the toolbar, menu bar, and status bar are showing

734 when the toolbar and menu bar are hidden but the status bar is showing');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (577, 9, 'related', 'Related topics', '- Functions reference

