INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (578, 5, 'notes', 'Notes', '- In FileMaker WebDirect, the content area includes the menu bar, status toolbar, scroll bars, and footer area.

- In FileMaker Go, the content area includes the layout but doesn''t include the device status bar, menu bar, or toolbar.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (578, 6, 'ref-example1', 'Example 1', 'Returns 400 in macOS when the current window width is 415.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (578, 7, 'ref-examplen', 'Example 2', 'The example below combines Get(WindowContentWidth) with Get(WindowWidth) to determine the width of the vertical scroll bar:

Get(WindowWidth) - Get(WindowContentWidth) returns 15 in macOS when the window width is 415.');
