INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (579, 0, 'ref-format', 'Format', 'Get ( WindowDesktopHeight )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (579, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (579, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (579, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (579, 4, 'ref-desc', 'Description', 'In FileMaker Pro, the desktop space is the area on the monitor screen in which the active window is located, excluding the taskbar in Windows or the menu bar and Dock in macOS.

In FileMaker WebDirect, the desktop space is the area on the main monitor screen. In macOS, all monitors have menu bars, and the main monitor is where the active window is located. In Windows, the main monitor is where the taskbar is located.

In FileMaker Go, the desktop space is the entire area of the screen.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (579, 5, 'notes', 'Notes', '- If the Data Viewer is the active window, the value returned by this function in the Data Viewer is based on the monitor on which the Data Viewer is displayed.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (579, 6, 'ref-example1', 'Example 1', 'Returns 1040 in Windows when there is a single monitor and its resolution is set to 1920 x 1080.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (579, 7, 'ref-examplen', 'Example 2', 'Returns 1347 in macOS when there is a single monitor, its resolution is set to 2560 x 1440, the menu bar is 23 points, and the Dock is 70 points and located at the bottom of the screen.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (579, 8, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (580, 0, 'ref-format', 'Format', 'Get ( WindowDesktopWidth )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (580, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (580, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (580, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (580, 4, 'ref-desc', 'Description', 'In FileMaker Pro, the desktop space is the area on the monitor screen in which the active window is located, excluding the taskbar in Windows or the menu bar and Dock in macOS.

In FileMaker WebDirect, the desktop space is the area on the main monitor screen. In macOS, all monitors have menu bars, and the main monitor is where the active window is located. In Windows, the main monitor is where the taskbar is located.

In FileMaker Go, the desktop space is the entire area of the screen.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (580, 5, 'notes', 'Notes', '- If the Data Viewer is the active window, the value returned by this function in the Data Viewer is based on the monitor on which the Data Viewer is displayed.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (580, 6, 'ref-example1', 'Example 1', 'Returns 1920 in Windows when there is a single monitor and its resolution is set to 1920 x 1080.

Returns 2560 in macOS when there is a single monitor and its resolution is set to 2560 x 1440.');
