INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (581, 0, 'ref-format', 'Format', 'Get ( WindowHeight )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (581, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (581, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (581, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (581, 4, 'ref-desc', 'Description', 'The height of the window is calculated from the top to bottom outer edges of the window. This position doesn''t include shadows or other effects applied to windows.

In FileMaker WebDirect, the window height does not include menus or toolbars that are part of the web browser.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (581, 5, 'notes', 'Notes', '- The window on which the script is acting may not necessarily be the foreground window.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (581, 6, 'ref-example1', 'Example 1', 'Get(WindowHeight) returns 300 when the current window''s height is 300 points.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (581, 7, 'related', 'Related topics', '- Functions reference

- About formulas

- About functions

- Defining calculation fields

- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (582, 0, 'ref-format', 'Format', 'Get ( WindowLeft )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (582, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (582, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (582, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (582, 4, 'ref-desc', 'Description', 'Except for card windows, the origin of the reference coordinate system is at the leftmost corner of the screen below the menu bar in macOS. In Windows, the origin is the left edge of the screen. A negative value indicates the portion of the left side of the window that is hidden.

For card windows, the origin is the left edge of the layout in the parent window. A negative value indicates the portion of the left side of the card that is left of the layout in the parent window.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (582, 5, 'notes', 'Notes', '-
The window on which the script is acting may not necessarily be the foreground window.

-
In FileMaker WebDirect, this function is supported only for cards.

-
Windows: Functions and script steps that work with windows refer to the outer edges of a window. See Get(WindowTop).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (582, 6, 'ref-example1', 'Example 1', 'Returns 52 when the outer edge of the active window is 52 points from the left edge of the screen.

Returns 0 when the active window is 0 points from the left edge of the screen.

For an example script, see New Window script step.');
