INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (583, 0, 'ref-format', 'Format', 'Get ( WindowMode )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (583, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (583, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (583, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (583, 4, 'ref-desc', 'Description', 'Returns:

- 0 for Browse mode

- 1 for Find mode

- 2 for Preview mode

- 3 if printing is in progress

- 4 if evaluating the function from the Data Viewer and the current window is in Layout mode

If a script using this function runs while the file is in Layout mode, FileMaker Pro switches to Browse mode and returns 0. If there are multiple windows open in the current database file, each window can have its own window mode value, but results are returned for only the foreground window.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (583, 5, 'ref-example1', 'Example 1', 'Returns 2 if the file is in Preview mode when the function is evaluated.');
