- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (584, 0, 'ref-format', 'Format', 'Get ( WindowName )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (584, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (584, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (584, 3, 'ref-orig', 'Originated in version', '7.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (584, 4, 'ref-desc', 'Description', 'Returns an empty string if there is no window.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (584, 5, 'notes', 'Notes', '-
The window on which the script is acting may not necessarily be the foreground window.

-
You can set the window name with the Set Window Title script step.

-
Window names aren''t required to be unique. To get a window''s unique identifier, use the Get(WindowUUID) function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (584, 6, 'ref-example1', 'Example 1', 'There are two windows, Teachers and Students, displaying the same layout that includes an unstored calculation field containing Get(WindowName). Teachers is returned when the Teachers window is refreshed, and Students is returned when the Students window is refreshed.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (584, 7, 'related', 'Related topics', '-
