Get(WindowUUID) function');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (585, 0, 'ref-format', 'Format', 'Get ( WindowOrientation )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (585, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (585, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (585, 3, 'ref-orig', 'Originated in version', '13.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (585, 4, 'ref-desc', 'Description', 'In FileMaker Pro and FileMaker Go only, returns:

-
-2 for landscape left

-
-1 for landscape right

-
0 for square (FileMaker Pro and FileMaker WebDirect only)

-
1 for portrait

-
2 for portrait upside down');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (585, 5, 'notes', 'Notes', '- The window on which the script is acting may not necessarily be the foreground window.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (585, 6, 'ref-example1', 'Example 1', 'If the window that the current script is acting on is in portrait orientation, Get(WindowOrientation) returns 1.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (585, 7, 'ref-examplen', 'Example 2', 'A calculation field named Orientation uses Get(WindowOrientation) to return a value as listed above. Another calculation field references the Orientation field and uses the If function, which returns Portrait if the Orientation field returns a value greater than 0 and returns Landscape if the Orientation field returns a value less than 0:

If ( Orientation > 0 ; "Portrait" ; "Landscape" )');
