- Using operators in formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (586, 0, 'ref-format', 'Format', 'Get ( WindowStyle )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (586, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (586, 2, 'ref-return', 'Data type returned', 'number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (586, 3, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (586, 4, 'ref-desc', 'Description', 'Returns:

- 0 (zero) if the window is a document window

- 1 if the window is a floating document window

- 2 if the window is a dialog window

- 3 if the window is a card');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (586, 5, 'notes', 'Notes', '- The window on which the script is acting may not necessarily be the foreground window.

- In FileMaker WebDirect, this function returns 0 or 3.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (586, 6, 'ref-example1', 'Example 1', 'Returns 0 if the current window is a document window when the function is evaluated.');
