INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (589, 5, 'ref-example1', 'Example 1', 'Returns 1 when the current window is visible.

Returns 0 when the current window has been hidden using the Hide Window command in FileMaker Pro.

For an example script, see Close Window script step.');
