INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (592, 5, 'ref-example1', 'Example 1', 'BaseTableComment ( "" ; "Contacts" ) returns the comment for the Contacts base table in the current file, which is Contacts at companies stored in the Customers table.');
