INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (595, 0, 'ref-format', 'Format', 'DatabaseNames');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (595, 1, 'ref-param', 'Parameters', 'None');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (595, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (595, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (595, 4, 'ref-desc', 'Description', 'Listed items are separated by carriage returns. The names returned do not include file extensions.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (595, 5, 'notes', 'Notes', '- If your database is hosted on another computer, DatabaseNames returns a list of the names of local client and remote database files open only on the client computer.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (595, 6, 'ref-example1', 'Example 1', 'To determine whether Customers is one of the files currently open, use the DatabaseNames function with the FilterValues function in the formula:

Copy

FilterValues ( DatabaseNames ; "Customers" )

If the formula returns any text value, then Customers is open.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (595, 7, 'ref-examplen', 'Example 2', 'If you want to know how many files with the same name are open, use the DatabaseNames function with the PatternCount function in the formula:

Copy

PatternCount (
    FilterValues ( DatabaseNames ; "Customers" ) ;
    "Customers"
)

This will tell you how many files named Customers are open.');
