INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (596, 5, 'ref-example1', 'Example 1', 'FieldAnnotation ( "" ; "Phone Number" ) returns the annotation for the Phone Number field in the current table in the current file, which is Customer''s home telephone number.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (596, 6, 'ref-examplen', 'Example 2', 'FieldAnnotation ( "Customers" ; "Accounts::Current Balance" ) returns the annotation for the Current Balance field in the Accounts table in the open file named Customers, which is Customer''s current balance.');
