INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (597, 0, 'ref-format', 'Format', 'FieldBounds ( fileName ; layoutName ; fieldName )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (597, 1, 'ref-param', 'Parameters', 'fileName - the name of an open database file (local or remote).

layoutName - the name of a layout in the specified database file.

fieldName - the name of a field on the specified layout.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (597, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (597, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (597, 4, 'ref-desc', 'Description', 'The location returned is measured from the top-left corner of the layout (regardless of printer margins) and is specified in this order: position of left field boundary, position of top field boundary, position of right field boundary, position of bottom field boundary, degree of rotation (measured in a counter-clockwise direction; 0 degrees for unrotated).');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (597, 5, 'notes', 'Notes', '- Your layout begins where your margins end. Because field boundaries are measured from the left side and top of the layout, boundaries returned by FieldBounds never change unless you move or re-size a field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (597, 6, 'ref-example1', 'Example 1', 'FieldBounds ( "Customers" ; "Layout #1" ; "Field" ) returns 36 48 295 65 0 in the example below. Notice that all parameters are enclosed in quotation marks.');
