INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (598, 5, 'ref-example1', 'Example 1', 'FieldComment ( "Customers" ; "Phone Number" ) returns "Customer''s home telephone number" if it was entered as a comment for the Phone Number field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (598, 6, 'ref-examplen', 'Example 2', 'FieldComment ( "Customers" ; "Accounts::Current Balance" ) returns "Customer''s current balance" if it was entered as a comment for the Current Balance field in the Accounts table.');
