INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (600, 4, 'ref-desc', 'Description', 'Listed items are separated by carriage returns.

Related fields are returned as TableID::RelatedFieldID.

For example, 12::4, where 12 is the ID of the table and 4 is the ID of the related field.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (600, 5, 'ref-example1', 'Example 1', 'FieldIDs ( "Customers" ; "" ) returns IDs of all unique fields in the default table of Customers.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (600, 6, 'ref-examplen', 'Example 2', 'FieldIDs ( "Customers" ; "Layout#5" ) returns IDs of all unique fields, including related fields, on Layout#5 in Customers.');
