INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (608, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (608, 3, 'ref-orig', 'Originated in version', '8.5');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (608, 4, 'ref-desc', 'Description', 'Listed items are separated by carriage returns. Layout objects without object names are not returned. If layoutName isn''t specified, then no object names are returned.

Named tab controls, grouped objects, and portal objects that contain other named objects are followed by a list of those named objects enclosed in angle brackets (< >). The angle brackets are shown even if there are no named objects contained within the named tab controls, grouped objects, or portal objects.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (608, 5, 'ref-example1', 'Example 1', 'LayoutObjectNames ("Customers";"Data Entry") returns a list of named objects in the Customers database file that appear on the Data Entry layout.');
