INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (617, 2, 'ref-return', 'Data type returned', 'text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (617, 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (617, 4, 'ref-desc', 'Description', 'Use the optional fileName parameter to only return windows that are based on the specified file. The window could be visible, hidden, or minimized. The order of the names in the list matches the current stacking order of the windows. The visible windows are listed first, then the minimized windows, and then the hidden windows. If there are no databases or windows open, an empty string is returned.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (617, 5, 'notes', 'Notes', '- Even if you close a file, it may remain open as a hidden file if the window of any other file is displaying data from that file. (For example, another window may be displaying related data from the file you attempted to close.) FileMaker Pro will close the file when you close all the dependent windows.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (617, 6, 'ref-example1', 'Example 1', 'WindowNames returns Customers and Invoices separated by a carriage return when those windows are currently open.');
