INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (619, 0, 'ref-format', 'Format', 'GetSensor ( sensorName {; option1 ; option2 } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (619, 1, 'ref-param', 'Parameters', 'sensorName - the name of a supported sensor (see below).

option1 - optional parameter for the specified sensor.

option2 - optional parameter for the specified sensor.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (619, 2, 'ref-return', 'Data type returned', 'text, number');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (619, 3, 'ref-orig', 'Originated in version', '17.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (619, 4, 'ref-desc', 'Description', 'Use this function to capture information provided by sensors for an iOS or iPadOS device running FileMaker Go. For example, you can find out the distance or number of steps traveled by a user; or the acceleration, speed, heading, and attitude for a device.

Sensors
sensorName
Returns
Data type returned
option1
option2
Battery

batteryLevel
The battery charge level (from 0.0 to 1.0).
number


batteryStatus
A number representing the status of the battery charge:
1 - unplugged
2 - charging
3 - plugged in and full
number







Location

location
The current location of a device in the format:

latitude (in degrees)
longitude (in degrees)
horizontal accuracy (+/- accuracy in meters)
text1
accuracy (in meters)
timeout (in seconds)
locationValues
The current location of a device in the format:

latitude (in degrees)
longitude (in degrees)
altitude (in meters)
horizontal accuracy (+/- accuracy in meters)
vertical accuracy (+/- accuracy in meters)
age (in minutes)
text1
accuracy (in meters)
timeout (in seconds)





Attitude, speed, and acceleration

attitude
The attitude for the device in radians in the format:

roll
pitch
yaw
text1


rotationRate
The rotation rate of the device (in radians per second) in the format:

x
y
z
text1


accelerationByUser
The acceleration the user is giving to the device in meters per second squared (m/s2) in the format:

x
y
z
text1


accelerationByGravity
The gravity acceleration in meters per second squared (m/s2) in the format:

x
y
z
text1


speed
The speed of the device in meters per second.
number
accuracy (in meters)
timeout (in seconds)
heading
The current direction of movement (in degrees). It returns a value from 0.0 to 359.9 degrees.
number
accuracy (in meters)
timeout (in seconds)





Magnetic

magneticField
The magnetic field vector (in microteslas), with respect to the current attitude of the device, in the format:

x
y
z
text1


compassMagneticHeading
The orientation of the user''s device (in degrees) relative to magnetic north. It returns a value from 0.0 to 359.9 degrees.
number
accuracy (in meters)
timeout (in seconds)
compassTrueHeading
The orientation of the user''s device (in degrees) relative to true north. It returns a value from 0.0 to 359.9 degrees.
number
accuracy (in meters)
timeout (in seconds)





Step counts

stepCount
The number of steps detected by the device for the specified duration.
number
forPastSeconds

stepDistance
The estimated distance (in meters) traveled by the user for the specified duration.
number
forPastSeconds

stepFloorsUp
The approximate number of floors ascended by the user for the specified duration.
number
forPastSeconds

stepFloorsDown
The approximate number of floors descended by the user for the specified duration.
number
forPastSeconds






Air pressure

airPressure
The recorded air pressure (in kilopascals).
number







List of sensors

available
A list of available sensorName values for the device. The values are separated by carriage returns.
text


- The data is returned as a list of numbers separated by carriage returns.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (619, 5, 'notes', 'Notes', '- accuracy is a number that represents a distance in meters. The default value for accuracy is 100 meters.

- timeout is a number that represents the longest time (in seconds) it will take to get the data. The default value for timeout is 10; the maximum value is 600.

- The default value for forPastSeconds is the number of seconds since midnight.

- FileMaker Go returns an empty string if the sensor is not available for the device.

- The values for location are the same as for the Location function.

- The values for locationValues are the same as for the LocationValues function.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (619, 6, 'ref-example1', 'Example 1', 'GetSensor ( "stepCount"; 3600 ) returns 8000 if the user has taken 8000 steps in the past hour.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (619, 7, 'related', 'Related topics', '- Functions reference

- About functions

- About formulas');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (620, 0, 'ref-format', 'Format', 'Location ( accuracy {; timeout } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (620, 1, 'ref-param', 'Parameters', 'accuracy - any numeric expression or field containing a number that represents the requested accuracy in meters.

timeout - any numeric expression or field containing a number that represents the most time it will take to fetch the location. Measured in seconds, the default value is 60.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (620, 2, 'ref-return', 'Data type returned', 'Text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (620, 3, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (620, 4, 'ref-desc', 'Description', 'This function returns the current latitude, longitude, and achieved accuracy on a device running FileMaker Go. The location is obtained via GPS, cellular network, or Wi-Fi.

Returns and caches the location of a device in the format latitude, longitude, accuracy. You can use the values that are returned to query map services. The Location function returns the horizontal accuracy achieved in meters and fetches the location values until timeout. If you cancel the process, FileMaker Go returns the most accurate location in the cache (if any).

If no location is received, FileMaker Go returns an empty string. In FileMaker Pro, Location returns an empty string.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (620, 5, 'notes', 'Notes', '-
To avoid excessive battery consumption and repeat fetches, specify a smaller number for timeout.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (620, 6, 'ref-example1', 'Example 1', 'Location ( 100; 40 ) takes up to 40 seconds to return the latitude and longitude with a requested accuracy of 100 meters (the achieved accuracy was 65 meters).

+37.343123, -122.017593, +65.000000');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (620, 7, 'related', 'Related topics', '-
Functions reference

-
About functions

-
About formulas

-
LocationValues function');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (621, 0, 'ref-format', 'Format', 'LocationValues ( accuracy {; timeout } )');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (621, 1, 'ref-param', 'Parameters', 'accuracy - any numeric expression or field containing a number that represents a distance in meters.

timeout - any numeric expression or field containing a number that represents the most time it will take to fetch the location. Measured in seconds, the default value is 60.

Parameters in braces { } are optional.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (621, 2, 'ref-return', 'Data type returned', 'Text');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (621, 3, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (621, 4, 'ref-desc', 'Description', 'This function returns the current latitude, longitude, and altitude on a device running FileMaker Go; returns the horizontal and vertical accuracy of the values returned; and number of minutes since the values were returned. The location is obtained via GPS, cellular network, or Wi-Fi.

Returns and caches the current location of a device in the format:

Copy

latitude
longitude
altitude (in meters)
horizontal accuracy (+/- accuracy in meters)
vertical accuracy (+/- accuracy in meters)
age of value in minutes (0.2 would represent 0.2 minutes or 12 seconds ago)

You can use the GetValue function to retrieve any of the six carriage return-delimited values above.

LocationValues fetches the location values until the requested accuracy is met or until timeout. If you cancel the process, FileMaker Go returns the most accurate location in the cache (if any). If no location is received, FileMaker Go returns an empty string.

In FileMaker Pro, LocationValues returns an empty string.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (621, 5, 'notes', 'Notes', '- Each returned value, except that last, ends with a carriage return.

- To avoid excessive battery consumption and repeat fetches, specify a larger number for accuracy and a smaller number for timeout.');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (621, 6, 'ref-example1', 'Example 1', 'LocationValues ( 100 ; 40 ) returns the following location for a device:

37.406489
-121.983428
0.0545050
65
10
0.001236');
INSERT INTO "calc_help_sections" ("help_page_id", "position", "section_key", "heading", "body_text") VALUES (621, 7, 'related', 'Related topics', '- Functions reference

